2	 * WorkflowEngine
3	 *
4	 * Executes and manages workflows with support for dependencies, parallelism,
5	 * rollback, and distributed execution.
6	 */
7	
8	import { EventEmitter } from 'events';
9	import { Task } from '../domain/Task';
10	import type { SwarmCoordinator } from '../../coordination/application/SwarmCoordinator';
11	import type {
12	  MemoryBackend,
13	  PluginManagerInterface,
14	  Task as ITask,
15	  TaskResult,
16	  WorkflowDefinition,
17	  WorkflowResult,
18	  WorkflowState,
19	  WorkflowStatus,
20	  WorkflowMetrics,
21	  WorkflowDebugInfo
22	} from '../../shared/types';
23	
24	export interface WorkflowEngineOptions {
25	  coordinator: SwarmCoordinator;
26	  memoryBackend?: MemoryBackend;
27	  eventBus?: EventEmitter;
28	  pluginManager?: PluginManagerInterface;
29	}
30	
31	interface WorkflowExecution {
32	  id: string;
33	  state: WorkflowState;
34	  promise?: Promise<WorkflowResult>;
35	  resolve?: (result: WorkflowResult) => void;
36	  reject?: (error: Error) => void;
37	  executionOrder: string[];
38	  taskTimings: Record<string, { start: number; end: number; duration: number }>;
39	  eventLog: Array<{ timestamp: number; event: string; data: unknown }>;
40	  memorySnapshots: Array<{ timestamp: number; snapshot: Record<string, unknown> }>;
41	}
42	
43	export class WorkflowEngine {
44	  private coordinator: SwarmCoordinator;
45	  private memoryBackend?: MemoryBackend;
46	  private eventBus: EventEmitter;
47	  private pluginManager?: PluginManagerInterface;
48	  private workflows: Map<string, WorkflowExecution>;
49	  private initialized: boolean = false;
50	
51	  constructor(options: WorkflowEngineOptions) {
52	    this.coordinator = options.coordinator;
53	    this.memoryBackend = options.memoryBackend;
54	    this.eventBus = options.eventBus || new EventEmitter();
55	    this.pluginManager = options.pluginManager;
56	    this.workflows = new Map();
57	  }
58	
59	  /**
60	   * Initialize the workflow engine
61	   */
62	  async initialize(): Promise<void> {
63	    if (this.initialized) return;
64	    this.initialized = true;
65	  }
66	
67	  /**
68	   * Shutdown the workflow engine
69	   */
70	  async shutdown(): Promise<void> {
71	    // Cancel all running workflows
72	    for (const [id, execution] of this.workflows.entries()) {
73	      if (execution.state.status === 'in-progress') {
74	        execution.state.status = 'cancelled';
75	        if (execution.reject) {
76	          execution.reject(new Error('Workflow engine shutdown'));
77	        }
78	      }
79	    }
80	    this.workflows.clear();
81	    this.initialized = false;
82	  }
83	
84	  /**
85	   * Execute a single task
86	   */
87	  async executeTask(task: ITask, agentId: string): Promise<TaskResult> {
88	    // Store task start
89	    if (this.memoryBackend) {
90	      await this.memoryBackend.store({
91	        id: `task-start-${task.id}`,
92	        agentId,
93	        content: `Task ${task.id} started`,
94	        type: 'task-start',
95	        timestamp: Date.now(),
96	        metadata: { taskId: task.id, agentId }
97	      });
98	    }
99	
100	    const result = await this.coordinator.executeTask(agentId, task);
101	
102	    // Store task completion
103	    if (this.memoryBackend) {
104	      await this.memoryBackend.store({
105	        id: `task-complete-${task.id}`,
106	        agentId,
107	        content: `Task ${task.id} ${result.status}`,
108	        type: 'task-complete',
109	        timestamp: Date.now(),
110	        metadata: { taskId: task.id, agentId, status: result.status, duration: result.duration }
111	      });
112	    }
113	
114	    return result;
115	  }
116	
117	  /**
118	   * Execute a workflow
119	   */
120	  async executeWorkflow(workflow: WorkflowDefinition): Promise<WorkflowResult> {
121	    const execution = this.createExecution(workflow);
122	    this.workflows.set(workflow.id, execution);
123	
124	    // Invoke before execute hook
125	    if (this.pluginManager) {
126	      await this.pluginManager.invokeExtensionPoint('workflow.beforeExecute', workflow);
127	    }
128	
129	    this.eventBus.emit('workflow:started', {
130	      workflowId: workflow.id,
131	      taskCount: workflow.tasks.length
132	    });
133	
134	    execution.eventLog.push({
135	      timestamp: Date.now(),
136	      event: 'workflow:started',
137	      data: { workflowId: workflow.id }
138	    });
139	
140	    try {
141	      const result = await this.runWorkflow(execution, workflow);
142	
143	      // Invoke after execute hook
144	      if (this.pluginManager) {
145	        await this.pluginManager.invokeExtensionPoint('workflow.afterExecute', result);
146	      }
147	
148	      this.eventBus.emit('workflow:completed', {
149	        workflowId: workflow.id,
150	        result
151	      });
152	
153	      return result;
154	    } catch (error) {
155	      const failedResult: WorkflowResult = {
156	        id: workflow.id,
157	        status: 'failed',
158	        tasksCompleted: execution.state.completedTasks.length,
159	        errors: [error instanceof Error ? error : new Error(String(error))],
160	        executionOrder: execution.executionOrder
161	      };
162	
163	      // Handle rollback if configured
164	      if (workflow.rollbackOnFailure) {
165	        await this.rollbackWorkflow(execution, workflow);
166	      }
167	
168	      this.eventBus.emit('workflow:failed', {
169	        workflowId: workflow.id,
170	        error
171	      });
172	
173	      return failedResult;
174	    }
175	  }
176	
177	  /**
178	   * Start a workflow (returns promise for later await)
179	   */
180	  startWorkflow(workflow: WorkflowDefinition): Promise<WorkflowResult> {
181	    const promise = this.executeWorkflow(workflow);
182	    const execution = this.workflows.get(workflow.id);
183	    if (execution) {
184	      execution.promise = promise;
185	    }
186	    return promise;
187	  }
188	
189	  /**
190	   * Pause a workflow
191	   */
192	  async pauseWorkflow(workflowId: string): Promise<void> {
193	    const execution = this.workflows.get(workflowId);
194	    if (execution && execution.state.status === 'in-progress') {
195	      execution.state.status = 'paused';
196	      execution.eventLog.push({
197	        timestamp: Date.now(),
198	        event: 'workflow:paused',
199	        data: { workflowId }
200	      });
201	    }
202	  }
203	
204	  /**
205	   * Resume a workflow
206	   */
207	  async resumeWorkflow(workflowId: string): Promise<void> {
208	    const execution = this.workflows.get(workflowId);
209	    if (execution && execution.state.status === 'paused') {
210	      execution.state.status = 'in-progress';
211	      execution.eventLog.push({
212	        timestamp: Date.now(),
213	        event: 'workflow:resumed',
214	        data: { workflowId }
215	      });
216	    }
217	  }
218	
219	  /**
220	   * Get workflow state
221	   */
222	  async getWorkflowState(workflowId: string): Promise<WorkflowState> {
223	    const execution = this.workflows.get(workflowId);
224	    if (!execution) {
225	      throw new Error(`Workflow ${workflowId} not found`);
226	    }
227	    return execution.state;
228	  }
229	
230	  /**
231	   * Execute tasks in parallel
232	   */
233	  async executeParallel(tasks: ITask[]): Promise<TaskResult[]> {
234	    return this.coordinator.executeTasksConcurrently(tasks);
235	  }
236	
237	  /**
238	   * Execute a distributed workflow
239	   */
240	  async executeDistributedWorkflow(
241	    workflow: WorkflowDefinition,
242	    coordinators: SwarmCoordinator[]
243	  ): Promise<WorkflowResult> {
244	    // Distribute tasks across coordinators
245	    const tasksPerCoordinator = Math.ceil(workflow.tasks.length / coordinators.length);
246	    const results: TaskResult[] = [];
247	    const errors: Error[] = [];
248	
249	    const taskChunks = [];
250	    for (let i = 0; i < workflow.tasks.length; i += tasksPerCoordinator) {
251	      taskChunks.push(workflow.tasks.slice(i, i + tasksPerCoordinator));
252	    }
253	
254	    await Promise.all(
255	      taskChunks.map(async (tasks, index) => {
256	        const coordinator = coordinators[index % coordinators.length];
257	        for (const task of tasks) {
258	          const agents = await coordinator.listAgents();
259	          if (agents.length > 0) {
260	            const result = await coordinator.executeTask(agents[0].id, task);
261	            results.push(result);
262	            if (result.status === 'failed') {
263	              errors.push(new Error(result.error || 'Task failed'));
264	            }
265	          }
266	        }
267	      })
268	    );
269	
270	    return {
271	      id: workflow.id,
272	      status: errors.length === 0 ? 'completed' : 'failed',
273	      tasksCompleted: results.filter(r => r.status === 'completed').length,
274	      errors,
275	      executionOrder: workflow.tasks.map(t => t.id)
276	    };
277	  }
278	
279	  /**
280	   * Get workflow metrics
281	   */
282	  async getWorkflowMetrics(workflowId: string): Promise<WorkflowMetrics> {
283	    const execution = this.workflows.get(workflowId);
284	    if (!execution) {
285	      throw new Error(`Workflow ${workflowId} not found`);
286	    }
287	
288	    const totalTasks = execution.state.tasks.length;
289	    const completedTasks = execution.state.completedTasks.length;
290	    const durations = Object.values(execution.taskTimings).map(t => t.duration);
291	    const totalDuration = durations.reduce((a, b) => a + b, 0);
292	    const averageDuration = durations.length > 0 ? totalDuration / durations.length : 0;
293	
294	    return {
295	      tasksTotal: totalTasks,
296	      tasksCompleted: completedTasks,
297	      totalDuration,
298	      averageTaskDuration: averageDuration,
299	      successRate: totalTasks > 0 ? completedTasks / totalTasks : 0
300	    };
301	  }
302	
303	  /**
304	   * Get workflow debug info
305	   */
306	  async getWorkflowDebugInfo(workflowId: string): Promise<WorkflowDebugInfo> {
307	    const execution = this.workflows.get(workflowId);
308	    if (!execution) {
309	      throw new Error(`Workflow ${workflowId} not found`);
310	    }
311	
312	    return {
313	      executionTrace: execution.executionOrder.map((taskId, index) => ({
314	        taskId,
315	        timestamp: execution.taskTimings[taskId]?.start || Date.now(),
316	        action: 'execute'
317	      })),
318	      taskTimings: execution.taskTimings,
319	      memorySnapshots: execution.memorySnapshots,
320	      eventLog: execution.eventLog
321	    };
322	  }
323	
324	  /**
325	   * Restore a workflow from persisted state
326	   */
327	  async restoreWorkflow(workflowId: string): Promise<WorkflowState> {
328	    if (!this.memoryBackend) {
329	      throw new Error('Memory backend not available');
330	    }
331	
332	    const stateMemory = await this.memoryBackend.retrieve(`workflow-state-${workflowId}`);
333	    if (!stateMemory) {
334	      // Try alternate key
335	      const result = await this.memoryBackend.retrieve('workflow-state');
336	      if (result) {
337	        return JSON.parse(result.content);
338	      }
339	      throw new Error(`Workflow state not found for ${workflowId}`);
340	    }
341	
342	    return JSON.parse(stateMemory.content);
343	  }
344	
345	  // ============================================================================
346	  // Private Helper Methods
347	  // ============================================================================
348	
349	  private createExecution(workflow: WorkflowDefinition): WorkflowExecution {
350	    return {
351	      id: workflow.id,
352	      state: {
353	        id: workflow.id,
354	        name: workflow.name,
355	        tasks: workflow.tasks,
356	        status: 'in-progress',
357	        completedTasks: [],
358	        startedAt: Date.now()
359	      },
360	      executionOrder: [],
361	      taskTimings: {},
362	      eventLog: [],
363	      memorySnapshots: []
364	    };
365	  }
366	
367	  private async runWorkflow(
368	    execution: WorkflowExecution,
369	    workflow: WorkflowDefinition
370	  ): Promise<WorkflowResult> {
371	    const tasks = workflow.tasks.map(t => new Task(t));
372	    const completedTasks = new Set<string>();
373	    const errors: Error[] = [];
374	
375	    // Resolve execution order
376	    const orderedTasks = Task.resolveExecutionOrder(tasks);
377	
378	    for (const task of orderedTasks) {
379	      // Check if paused
380	      while (execution.state.status === 'paused') {
381	        await new Promise(resolve => setTimeout(resolve, 100));
382	      }
383	
384	      if (execution.state.status === 'cancelled') {
385	        break;
386	      }
387	
388	      execution.state.currentTask = task.id;
389	
390	      const startTime = Date.now();
391	
392	      try {
393	        // Handle nested workflows
394	        if (task.isWorkflow() && task.workflow) {
395	          const nestedResult = await this.executeWorkflow(task.workflow);
396	          if (nestedResult.status === 'failed') {
397	            throw new Error(`Nested workflow failed`);
398	          }
399	        } else {
400	          // Get assigned agent or distribute
401	          let agentId = task.assignedTo;
402	          if (!agentId) {
403	            const agents = await this.coordinator.listAgents();
404	            const suitable = agents.find(a => a.canExecute(task.type));
405	            agentId = suitable?.id;
406	          }
407	
408	          if (!agentId) {
409	            throw new Error(`No agent available for task ${task.id}`);
410	          }
411	
412	          const result = await this.executeTask(task, agentId);
413	          if (result.status === 'failed') {
414	            throw new Error(result.error || 'Task execution failed');
415	          }
416	        }
417	
418	        const endTime = Date.now();
419	        execution.taskTimings[task.id] = {
420	          start: startTime,
421	          end: endTime,
422	          duration: endTime - startTime
423	        };
424	
425	        completedTasks.add(task.id);
426	        execution.state.completedTasks.push(task.id);
427	        execution.executionOrder.push(task.id);
428	
429	        this.eventBus.emit('workflow:taskComplete', {
430	          workflowId: workflow.id,
431	          taskId: task.id
432	        });
433	
434	        execution.eventLog.push({
435	          timestamp: endTime,
436	          event: 'task:completed',
437	          data: { taskId: task.id, duration: endTime - startTime }
438	        });
439	      } catch (error) {
440	        errors.push(error instanceof Error ? error : new Error(String(error)));
441	
442	        if (workflow.rollbackOnFailure) {
443	          throw error; // Let outer handler deal with rollback
444	        }
445	      }
446	    }
447	
448	    execution.state.status = errors.length > 0 ? 'failed' : 'completed';
449	    execution.state.completedAt = Date.now();
450	
451	    return {
452	      id: workflow.id,
453	      status: errors.length > 0 ? 'failed' : 'completed',
454	      tasksCompleted: completedTasks.size,
455	      errors,
456	      executionOrder: execution.executionOrder,
457	      duration: execution.state.completedAt - (execution.state.startedAt || 0)
458	    };
459	  }
460	
461	  private async rollbackWorkflow(
462	    execution: WorkflowExecution,
463	    workflow: WorkflowDefinition
464	  ): Promise<void> {
465	    // Rollback in reverse order
466	    const completedTaskIds = [...execution.state.completedTasks].reverse();
467	
468	    for (const taskId of completedTaskIds) {
469	      const task = workflow.tasks.find(t => t.id === taskId);
470	      if (task?.onRollback) {
471	        try {
472	          await task.onRollback();
473	          execution.eventLog.push({
474	            timestamp: Date.now(),
475	            event: 'task:rolledback',
476	            data: { taskId }
477	          });
478	        } catch (error) {
479	          // Log but continue rollback
480	          execution.eventLog.push({
481	            timestamp: Date.now(),
482	            event: 'rollback:error',
483	            data: { taskId, error: String(error) }
484	          });
485	        }
486	      }
487	    }
488	  }
489	}
