1	/**
2	 * SwarmCoordinator
3	 *
4	 * Coordinates multi-agent swarms with support for hierarchical and mesh topologies.
5	 * Based on agentic-flow's AttentionCoordinator pattern.
6	 */
7	
8	import { EventEmitter } from 'events';
9	import { Agent } from '../../agent-lifecycle/domain/Agent';
10	import { Task } from '../../task-execution/domain/Task';
11	import type {
12	  AgentConfig,
13	  AgentMessage,
14	  AgentMetrics,
15	  ConsensusDecision,
16	  ConsensusResult,
17	  MeshConnection,
18	  MemoryBackend,
19	  PluginManagerInterface,
20	  SwarmConfig,
21	  SwarmHierarchy,
22	  SwarmState,
23	  SwarmTopology,
24	  Task as ITask,
25	  TaskAssignment,
26	  TaskResult
27	} from '../../shared/types';
28	
29	export interface SwarmCoordinatorOptions extends SwarmConfig {
30	  topology: SwarmTopology;
31	  memoryBackend?: MemoryBackend;
32	  eventBus?: EventEmitter;
33	  pluginManager?: PluginManagerInterface;
34	}
35	
36	export class SwarmCoordinator {
37	  private topology: SwarmTopology;
38	  private agents: Map<string, Agent>;
39	  private memoryBackend?: MemoryBackend;
40	  private eventBus: EventEmitter;
41	  private pluginManager?: PluginManagerInterface;
42	  private agentMetrics: Map<string, AgentMetrics>;
43	  private connections: MeshConnection[];
44	  private initialized: boolean = false;
45	
46	  constructor(options: SwarmCoordinatorOptions) {
47	    this.topology = options.topology;
48	    this.memoryBackend = options.memoryBackend;
49	    this.eventBus = options.eventBus || new EventEmitter();
50	    this.pluginManager = options.pluginManager;
51	    this.agents = new Map();
52	    this.agentMetrics = new Map();
53	    this.connections = [];
54	  }
55	
56	  /**
57	   * Initialize the coordinator
58	   */
59	  async initialize(): Promise<void> {
60	    if (this.initialized) return;
61	    this.initialized = true;
62	  }
63	
64	  /**
65	   * Shutdown the coordinator
66	   */
67	  async shutdown(): Promise<void> {
68	    // Terminate all agents
69	    for (const agent of this.agents.values()) {
70	      agent.terminate();
71	    }
72	    this.agents.clear();
73	    this.connections = [];
74	    this.agentMetrics.clear();
75	    this.initialized = false;
76	  }
77	
78	  /**
79	   * Spawn a new agent
80	   */
81	  async spawnAgent(config: AgentConfig): Promise<Agent> {
82	    const agent = new Agent(config);
83	    this.agents.set(agent.id, agent);
84	
85	    // Initialize metrics
86	    this.agentMetrics.set(agent.id, {
87	      agentId: agent.id,
88	      tasksCompleted: 0,
89	      tasksFailed: 0,
90	      averageExecutionTime: 0,
91	      successRate: 1.0,
92	      health: 'healthy'
93	    });
94	
95	    // Create connections based on topology
96	    this.updateConnections(agent);
97	
98	    // Emit spawn event
99	    this.eventBus.emit('agent:spawned', { agentId: agent.id, type: agent.type });
100	
101	    // Store in memory if backend available
102	    if (this.memoryBackend) {
103	      await this.memoryBackend.store({
104	        id: `agent-spawn-${agent.id}`,
105	        agentId: 'system',
106	        content: `Agent ${agent.id} spawned`,
107	        type: 'event',
108	        timestamp: Date.now(),
109	        metadata: { eventType: 'agent-spawn', agentId: agent.id, agentType: agent.type }
110	      });
111	    }
112	
113	    return agent;
114	  }
115	
116	  /**
117	   * List all agents
118	   */
119	  async listAgents(): Promise<Agent[]> {
120	    return Array.from(this.agents.values());
121	  }
122	
123	  /**
124	   * Terminate an agent
125	   */
126	  async terminateAgent(agentId: string): Promise<void> {
127	    const agent = this.agents.get(agentId);
128	    if (agent) {
129	      agent.terminate();
130	      this.agents.delete(agentId);
131	      this.agentMetrics.delete(agentId);
132	
133	      // Remove connections
134	      this.connections = this.connections.filter(
135	        c => c.from !== agentId && c.to !== agentId
136	      );
137	
138	      this.eventBus.emit('agent:terminated', { agentId });
139	    }
140	  }
141	
142	  /**
143	   * Distribute tasks across agents
144	   */
145	  async distributeTasks(tasks: ITask[]): Promise<TaskAssignment[]> {
146	    const assignments: TaskAssignment[] = [];
147	    const agentLoads = new Map<string, number>();
148	
149	    // Initialize load counts
150	    for (const agent of this.agents.values()) {
151	      agentLoads.set(agent.id, 0);
152	    }
153	
154	    // Sort tasks by priority
155	    const sortedTasks = Task.sortByPriority(tasks.map(t => new Task(t)));
156	
157	    for (const task of sortedTasks) {
158	      // Find suitable agents
159	      const suitableAgents = Array.from(this.agents.values()).filter(agent =>
160	        agent.canExecute(task.type) && agent.status === 'active'
161	      );
162	
163	      if (suitableAgents.length === 0) continue;
164	
165	      // Load balance: assign to agent with lowest load
166	      let bestAgent = suitableAgents[0];
167	      let lowestLoad = agentLoads.get(bestAgent.id) || 0;
168	
169	      for (const agent of suitableAgents) {
170	        const load = agentLoads.get(agent.id) || 0;
171	        if (load < lowestLoad) {
172	          lowestLoad = load;
173	          bestAgent = agent;
174	        }
175	      }
176	
177	      assignments.push({
178	        taskId: task.id,
179	        agentId: bestAgent.id,
180	        assignedAt: Date.now(),
181	        priority: task.priority
182	      });
183	
184	      agentLoads.set(bestAgent.id, (agentLoads.get(bestAgent.id) || 0) + 1);
185	    }
186	
187	    return assignments;
188	  }
189	
190	  /**
191	   * Execute a task on a specific agent
192	   */
193	  async executeTask(agentId: string, task: ITask): Promise<TaskResult> {
194	    const agent = this.agents.get(agentId);
195	    if (!agent) {
196	      return {
197	        taskId: task.id,
198	        status: 'failed',
199	        error: `Agent ${agentId} not found`,
200	        agentId
201	      };
202	    }
203	
204	    const startTime = Date.now();
205	    // ruflo#1872 — `agent.executeTask` can throw (mock rejection in
206	    // tests, real broker/network errors in production). Previously the
207	    // throw propagated up to the caller, defeating the
208	    // "TaskResult{status:'failed', error}" contract callers rely on
209	    // for graceful degradation. Wrap in try/catch so a crashed agent
210	    // produces a structured failure result instead of an unhandled
211	    // promise rejection.
212	    let result: TaskResult;
213	    try {
214	      result = await agent.executeTask(task);
215	    } catch (err) {
216	      result = {
217	        taskId: task.id,
218	        status: 'failed',
219	        error: err instanceof Error ? err.message : String(err),
220	        agentId,
221	      };
222	    }
223	    const duration = Date.now() - startTime;
224	
225	    // Update metrics
226	    const metrics = this.agentMetrics.get(agentId);
227	    if (metrics) {
228	      if (result.status === 'completed') {
229	        metrics.tasksCompleted++;
230	      } else {
231	        metrics.tasksFailed = (metrics.tasksFailed || 0) + 1;
232	      }
233	      const total = metrics.tasksCompleted + (metrics.tasksFailed || 0);
234	      metrics.successRate = metrics.tasksCompleted / total;
235	      metrics.averageExecutionTime =
236	        (metrics.averageExecutionTime * (total - 1) + duration) / total;
237	    }
238	
239	    // Store result in memory
240	    if (this.memoryBackend) {
241	      await this.memoryBackend.store({
242	        id: `task-result-${task.id}`,
243	        agentId,
244	        content: `Task ${task.id} ${result.status}`,
245	        type: result.status === 'completed' ? 'task-complete' : 'event',
246	        timestamp: Date.now(),
247	        metadata: {
248	          taskId: task.id,
249	          status: result.status,
250	          duration,
251	          error: result.error
252	        }
253	      });
254	    }
255	
256	    return result;
257	  }
258	
259	  /**
260	   * Execute multiple tasks concurrently
261	   */
262	  async executeTasksConcurrently(tasks: ITask[]): Promise<TaskResult[]> {
263	    const assignments = await this.distributeTasks(tasks);
264	    const results = await Promise.all(
265	      assignments.map(async assignment => {
266	        const task = tasks.find(t => t.id === assignment.taskId);
267	        if (!task) {
268	          return {
269	            taskId: assignment.taskId,
270	            status: 'failed' as const,
271	            error: 'Task not found'
272	          };
273	        }
274	        return this.executeTask(assignment.agentId, task);
275	      })
276	    );
277	    return results;
278	  }
279	
280	  /**
281	   * Send a message between agents
282	   */
283	  async sendMessage(message: AgentMessage): Promise<void> {
284	    const enhancedMessage = {
285	      ...message,
286	      timestamp: Date.now()
287	    };
288	
289	    this.eventBus.emit('agent:message', enhancedMessage);
290	  }
291	
292	  /**
293	   * Get swarm state
294	   */
295	  async getSwarmState(): Promise<SwarmState> {
296	    return {
297	      agents: Array.from(this.agents.values()),
298	      topology: this.topology,
299	      leader: this.getLeader()?.id,
300	      activeConnections: this.connections.length
301	    };
302	  }
303	
304	  /**
305	   * Get current topology
306	   */
307	  getTopology(): SwarmTopology {
308	    return this.topology;
309	  }
310	
311	  /**
312	   * Get swarm hierarchy (for hierarchical topology)
313	   */
314	  async getHierarchy(): Promise<SwarmHierarchy> {
315	    const leader = this.getLeader();
316	    const workers = Array.from(this.agents.values())
317	      .filter(a => a.role !== 'leader')
318	      .map(a => ({ id: a.id, parent: a.parent || leader?.id || '' }));
319	
320	    return {
321	      leader: leader?.id || '',
322	      workers
323	    };
324	  }
325	
326	  /**
327	   * Get mesh connections
328	   */
329	  async getMeshConnections(): Promise<MeshConnection[]> {
330	    return this.connections;
331	  }
332	
333	  /**
334	   * Scale agents
335	   */
336	  async scaleAgents(config: { type: string; count: number }): Promise<void> {
337	    // ruflo#1872 — `count` is the TARGET TOTAL of this agent type, not
338	    // a delta. Previously `count` was added to the existing count, so
339	    // calling `scaleAgents({count:3})` then `scaleAgents({count:2})`
340	    // ended up at 1+3+2=6 instead of the intuitive 2.
341	    const existingOfType = Array.from(this.agents.values()).filter(
342	      a => a.type === config.type
343	    );
344	    const currentCount = existingOfType.length;
345	    const targetCount = Math.max(0, Math.floor(config.count));
346	
347	    if (targetCount > currentCount) {
348	      // Scale up
349	      for (let i = currentCount; i < targetCount; i++) {
350	        await this.spawnAgent({
351	          id: `${config.type}-${Date.now()}-${i}`,
352	          type: config.type,
353	          capabilities: this.getDefaultCapabilities(config.type),
354	        });
355	      }
356	    } else if (targetCount < currentCount) {
357	      // Scale down — terminate the oldest first so deterministic.
358	      const toRemove = existingOfType.slice(0, currentCount - targetCount);
359	      for (const agent of toRemove) {
360	        await this.terminateAgent(agent.id);
361	      }
362	    }
363	  }
364	
365	  /**
366	   * Reach consensus among agents
367	   */
368	  async reachConsensus(
369	    decision: ConsensusDecision,
370	    agentIds: string[]
371	  ): Promise<ConsensusResult> {
372	    const votes: Array<{ agentId: string; vote: unknown }> = [];
373	
374	    for (const agentId of agentIds) {
375	      const agent = this.agents.get(agentId);
376	      if (agent) {
377	        // Simulate voting (in real implementation, would involve LLM calls)
378	        const vote = {
379	          agentId,
380	          vote: Math.random() > 0.5 ? 'approve' : 'reject'
381	        };
382	        votes.push(vote);
383	      }
384	    }
385	
386	    const approves = votes.filter(v => v.vote === 'approve').length;
387	    const consensusReached = approves > votes.length / 2;
388	
389	    return {
390	      decision: consensusReached ? decision.payload : null,
391	      votes,
392	      consensusReached
393	    };
394	  }
395	
396	  /**
397	   * Resolve task dependencies
398	   */
399	  async resolveTaskDependencies(tasks: ITask[]): Promise<ITask[]> {
400	    return Task.resolveExecutionOrder(tasks.map(t => new Task(t)));
401	  }
402	
403	  /**
404	   * Get agent metrics
405	   */
406	  async getAgentMetrics(agentId: string): Promise<AgentMetrics> {
407	    const metrics = this.agentMetrics.get(agentId);
408	    if (!metrics) {
409	      return {
410	        agentId,
411	        tasksCompleted: 0,
412	        averageExecutionTime: 0,
413	        successRate: 0,
414	        health: 'unhealthy'
415	      };
416	    }
417	    return metrics;
418	  }
419	
420	  /**
421	   * Reconfigure the swarm
422	   */
423	  async reconfigure(config: { topology: SwarmTopology }): Promise<void> {
424	    this.topology = config.topology;
425	
426	    // Rebuild connections based on new topology
427	    this.connections = [];
428	    for (const agent of this.agents.values()) {
429	      this.updateConnections(agent);
430	    }
431	  }
432	
433	  // ============================================================================
434	  // Private Helper Methods
435	  // ============================================================================
436	
437	  private getLeader(): Agent | undefined {
438	    return Array.from(this.agents.values()).find(a => a.role === 'leader');
439	  }
440	
441	  private updateConnections(agent: Agent): void {
442	    if (this.topology === 'mesh') {
443	      // In mesh, connect to all other agents
444	      for (const other of this.agents.values()) {
445	        if (other.id !== agent.id) {
446	          this.connections.push({
447	            from: agent.id,
448	            to: other.id,
449	            type: 'peer'
450	          });
451	        }
452	      }
453	    } else if (this.topology === 'hierarchical') {
454	      // In hierarchical, connect workers to leader
455	      const leader = this.getLeader();
456	      if (leader && agent.role !== 'leader') {
457	        this.connections.push({
458	          from: agent.id,
459	          to: leader.id,
460	          type: 'leader'
461	        });
462	      }
463	    }
464	  }
465	
466	  private getDefaultCapabilities(type: string): string[] {
467	    const defaults: Record<string, string[]> = {
468	      coder: ['code', 'refactor', 'debug'],
469	      tester: ['test', 'validate', 'e2e'],
470	      reviewer: ['review', 'analyze', 'security-audit'],
471	      coordinator: ['coordinate', 'manage', 'orchestrate'],
472	      designer: ['design', 'prototype'],
473	      deployer: ['deploy', 'release']
474	    };
475	    return defaults[type] || [];
476	  }
477	}
478	
479	export { SwarmCoordinator as default };
