1	/**
2	 * PluginManager
3	 *
4	 * Manages plugin lifecycle, dependencies, and extension point invocation.
5	 * Per ADR-004: Plugin-based architecture (microkernel pattern).
6	 */
7	
8	import { EventEmitter } from 'events';
9	import type {
10	  Plugin,
11	  ExtensionPoint,
12	  PluginMetadata,
13	  PluginManagerInterface
14	} from '../../shared/types';
15	import { PluginError } from '../../shared/types';
16	
17	export interface PluginManagerOptions {
18	  eventBus?: EventEmitter;
19	  coreVersion?: string;
20	}
21	
22	export class PluginManager implements PluginManagerInterface {
23	  private plugins: Map<string, Plugin>;
24	  private extensionPoints: Map<string, Array<{ pluginId: string; handler: ExtensionPoint['handler']; priority: number }>>;
25	  private eventBus: EventEmitter;
26	  private coreVersion: string;
27	  private initialized: boolean = false;
28	
29	  constructor(options: PluginManagerOptions = {}) {
30	    this.plugins = new Map();
31	    this.extensionPoints = new Map();
32	    this.eventBus = options.eventBus || new EventEmitter();
33	    this.coreVersion = options.coreVersion || '3.0.0';
34	  }
35	
36	  /**
37	   * Initialize the plugin manager
38	   */
39	  async initialize(): Promise<void> {
40	    if (this.initialized) return;
41	    this.initialized = true;
42	  }
43	
44	  /**
45	   * Shutdown the plugin manager and all plugins
46	   */
47	  async shutdown(): Promise<void> {
48	    // Shutdown plugins in reverse order of loading
49	    const pluginIds = Array.from(this.plugins.keys()).reverse();
50	    for (const pluginId of pluginIds) {
51	      await this.unloadPlugin(pluginId);
52	    }
53	    this.extensionPoints.clear();
54	    this.initialized = false;
55	  }
56	
57	  /**
58	   * Load and initialize a plugin
59	   */
60	  async loadPlugin(plugin: Plugin, config?: Record<string, unknown>): Promise<void> {
61	    // Check if already loaded
62	    if (this.plugins.has(plugin.id)) {
63	      await this.unloadPlugin(plugin.id);
64	    }
65	
66	    // Validate configuration if schema provided
67	    if (plugin.configSchema && config) {
68	      this.validateConfig(plugin.configSchema, config);
69	    }
70	
71	    // Check version compatibility
72	    if (plugin.minCoreVersion || plugin.maxCoreVersion) {
73	      this.checkVersionCompatibility(plugin);
74	    }
75	
76	    // Check dependencies
77	    if (plugin.dependencies) {
78	      for (const depId of plugin.dependencies) {
79	        if (!this.plugins.has(depId)) {
80	          throw new PluginError(
81	            `Plugin ${plugin.id} depends on ${depId} which is not loaded`,
82	            { pluginId: plugin.id, dependency: depId }
83	          );
84	        }
85	      }
86	    }
87	
88	    // Initialize plugin
89	    await plugin.initialize(config);
90	
91	    // Register plugin
92	    this.plugins.set(plugin.id, plugin);
93	
94	    // Register extension points
95	    const extensionPoints = plugin.getExtensionPoints();
96	    for (const ep of extensionPoints) {
97	      this.registerExtensionPoint(plugin.id, ep, plugin.priority);
98	    }
99	
100	    // Emit event
101	    this.eventBus.emit('plugin:loaded', { id: plugin.id, name: plugin.name });
102	  }
103	
104	  /**
105	   * Unload a plugin
106	   */
107	  async unloadPlugin(pluginId: string): Promise<void> {
108	    const plugin = this.plugins.get(pluginId);
109	    if (!plugin) return;
110	
111	    // Check if other plugins depend on this one
112	    for (const [otherId, other] of this.plugins.entries()) {
113	      if (other.dependencies?.includes(pluginId)) {
114	        throw new PluginError(
115	          `Cannot unload ${pluginId}: plugin ${otherId} depends on it`,
116	          { pluginId, dependentPluginId: otherId }
117	        );
118	      }
119	    }
120	
121	    // Shutdown plugin
122	    await plugin.shutdown();
123	
124	    // Remove extension points
125	    for (const [name, handlers] of this.extensionPoints.entries()) {
126	      this.extensionPoints.set(
127	        name,
128	        handlers.filter(h => h.pluginId !== pluginId)
129	      );
130	    }
131	
132	    // Remove plugin
133	    this.plugins.delete(pluginId);
134	
135	    // Emit event
136	    this.eventBus.emit('plugin:unloaded', { id: pluginId });
137	  }
138	
139	  /**
140	   * Reload a plugin with new version
141	   */
142	  async reloadPlugin(pluginId: string, plugin: Plugin): Promise<void> {
143	    await this.unloadPlugin(pluginId);
144	    await this.loadPlugin(plugin);
145	  }
146	
147	  /**
148	   * List all loaded plugins
149	   */
150	  listPlugins(): Plugin[] {
151	    return Array.from(this.plugins.values());
152	  }
153	
154	  /**
155	   * Get plugin metadata
156	   */
157	  getPluginMetadata(pluginId: string): PluginMetadata | undefined {
158	    const plugin = this.plugins.get(pluginId);
159	    if (!plugin) return undefined;
160	
161	    return {
162	      id: plugin.id,
163	      name: plugin.name,
164	      version: plugin.version,
165	      description: plugin.description,
166	      author: plugin.author,
167	      homepage: plugin.homepage
168	    };
169	  }
170	
171	  /**
172	   * Invoke all handlers for an extension point
173	   */
174	  async invokeExtensionPoint(name: string, context: unknown): Promise<unknown[]> {
175	    const handlers = this.extensionPoints.get(name) || [];
176	
177	    // Sort by priority (higher first)
178	    const sorted = [...handlers].sort((a, b) => b.priority - a.priority);
179	
180	    const results: unknown[] = [];
181	    for (const { handler, pluginId } of sorted) {
182	      try {
183	        const result = await handler(context);
184	        results.push(result);
185	      } catch (error) {
186	        // Include error in results but continue with other handlers
187	        results.push({
188	          error: error instanceof Error ? error.message : String(error),
189	          pluginId
190	        });
191	      }
192	    }
193	
194	    return results;
195	  }
196	
197	  /**
198	   * Get the core version
199	   */
200	  getCoreVersion(): string {
201	    return this.coreVersion;
202	  }
203	
204	  // ============================================================================
205	  // Private Helper Methods
206	  // ============================================================================
207	
208	  private registerExtensionPoint(
209	    pluginId: string,
210	    ep: ExtensionPoint,
211	    pluginPriority?: number
212	  ): void {
213	    const handlers = this.extensionPoints.get(ep.name) || [];
214	    handlers.push({
215	      pluginId,
216	      handler: ep.handler,
217	      priority: ep.priority ?? pluginPriority ?? 0
218	    });
219	    this.extensionPoints.set(ep.name, handlers);
220	  }
221	
222	  private validateConfig(schema: Record<string, unknown>, config: Record<string, unknown>): void {
223	    // Simple validation - check required fields
224	    const required = (schema as any).required as string[] | undefined;
225	    if (required) {
226	      for (const field of required) {
227	        if (!(field in config)) {
228	          throw new PluginError(
229	            `Missing required configuration field: ${field}`,
230	            { field, validation: 'required' }
231	          );
232	        }
233	      }
234	    }
235	  }
236	
237	  private checkVersionCompatibility(plugin: Plugin): void {
238	    const currentVersion = this.getCoreVersion();
239	    const coreVersion = this.parseVersion(currentVersion);
240	
241	    if (plugin.minCoreVersion) {
242	      const minVersion = this.parseVersion(plugin.minCoreVersion);
243	      if (this.compareVersions(coreVersion, minVersion) < 0) {
244	        throw new PluginError(
245	          `Plugin ${plugin.id} requires core version >= ${plugin.minCoreVersion}, but core version is ${currentVersion}`,
246	          { pluginId: plugin.id, minVersion: plugin.minCoreVersion, coreVersion: currentVersion }
247	        );
248	      }
249	    }
250	
251	    if (plugin.maxCoreVersion) {
252	      const maxVersion = this.parseVersion(plugin.maxCoreVersion);
253	      if (this.compareVersions(coreVersion, maxVersion) > 0) {
254	        throw new PluginError(
255	          `Plugin ${plugin.id} requires core version <= ${plugin.maxCoreVersion}, but core version is ${currentVersion}`,
256	          { pluginId: plugin.id, maxVersion: plugin.maxCoreVersion, coreVersion: currentVersion }
257	        );
258	      }
259	    }
260	  }
261	
262	  private parseVersion(version: string): number[] {
263	    return version.split('.').map(n => parseInt(n, 10) || 0);
264	  }
265	
266	  private compareVersions(a: number[], b: number[]): number {
267	    for (let i = 0; i < Math.max(a.length, b.length); i++) {
268	      const av = a[i] || 0;
269	      const bv = b[i] || 0;
270	      if (av !== bv) return av - bv;
271	    }
272	    return 0;
273	  }
274	}
