138	      }
139	    }
140	  }
141	
142	  /**
143	   * Get database path
144	   */
145	  getDbPath(): string {
146	    return this.dbPath;
147	  }
148	
149	  /**
150	   * Get memory count
151	   */
152	  getCount(): number {
153	    return this.memories.size;
154	  }
155	}
