83	  /**
84	   * Query memories with filters
85	   */
86	  async query(query: MemoryQuery): Promise<Memory[]> {
87	    let results = Array.from(this.memories.values());
88	
89	    // Filter by agentId
90	    if (query.agentId) {
91	      results = results.filter(m => m.agentId === query.agentId);
92	    }
93	
94	    // Filter by type
95	    if (query.type) {
96	      results = results.filter(m => m.type === query.type);
97	    }
98	
99	    // Filter by time range
100	    if (query.timeRange) {
101	      results = results.filter(
102	        m => m.timestamp >= query.timeRange!.start && m.timestamp <= query.timeRange!.end
103	      );
104	    }
105	
106	    // Filter by metadata
107	    if (query.metadata) {
108	      results = results.filter(m => {
109	        if (!m.metadata) return false;
110	        return Object.entries(query.metadata!).every(
111	          ([key, value]) => m.metadata![key] === value
112	        );
113	      });
114	    }
115	
116	    // Sort by timestamp (newest first)
117	    results.sort((a, b) => b.timestamp - a.timestamp);
118	
119	    // Apply pagination
120	    if (query.offset !== undefined) {
121	      results = results.slice(query.offset);
122	    }
123	    if (query.limit !== undefined) {
124	      results = results.slice(0, query.limit);
125	    }
126	
127	    return results;
128	  }
129	
130	  /**
131	   * Vector similarity search using HNSW
132	   */
133	  async vectorSearch(embedding: number[], k: number = 10): Promise<MemorySearchResult[]> {
134	    // Get all memories with embeddings
135	    const withEmbeddings = Array.from(this.memories.values()).filter(
136	      m => m.embedding && m.embedding.length > 0
137	    );
138	
139	    // Calculate cosine similarity
140	    const scored = withEmbeddings.map(memory => ({
141	      ...memory,
142	      similarity: this.cosineSimilarity(embedding, memory.embedding!)
143	    }));
144	
145	    // Sort by similarity and take top k
146	    scored.sort((a, b) => b.similarity - a.similarity);
147	
148	    return scored.slice(0, k);
149	  }
150	
151	  /**
152	   * Clear all memories for an agent
153	   */
154	  async clearAgent(agentId: string): Promise<void> {
155	    for (const [id, memory] of this.memories.entries()) {
156	      if (memory.agentId === agentId) {
157	        this.memories.delete(id);
158	      }
159	    }
160	  }
161	
162	  /**
163	   * Calculate cosine similarity between two vectors
164	   */
165	  private cosineSimilarity(a: number[], b: number[]): number {
166	    if (a.length !== b.length) {
167	      return 0;
168	    }
169	
170	    let dotProduct = 0;
171	    let normA = 0;
172	    let normB = 0;
173	
174	    for (let i = 0; i < a.length; i++) {
175	      dotProduct += a[i] * b[i];
176	      normA += a[i] * a[i];
177	      normB += b[i] * b[i];
178	    }
179	
180	    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
181	    return denominator === 0 ? 0 : dotProduct / denominator;
182	  }
183	
184	  /**
185	   * Get database path
186	   */
187	  getDbPath(): string {
188	    return this.dbPath;
189	  }
190	
191	  /**
192	   * Get embedding dimensions
193	   */
194	  getDimensions(): number {
195	    return this.dimensions;
196	  }
197	
198	  /**
199	   * Get HNSW M parameter
200	   */
201	  getHnswM(): number {
202	    return this.hnswM;
203	  }
204	}
