3	 *
4	 * Combines SQLite for structured queries with AgentDB for vector search.
5	 * Per ADR-009: Hybrid Memory Backend Default.
6	 */
7	
8	import type {
9	  Memory,
10	  MemoryBackend,
11	  MemoryQuery,
12	  MemorySearchResult
13	} from '../../shared/types';
14	import { SQLiteBackend } from './SQLiteBackend';
15	import { AgentDBBackend } from './AgentDBBackend';
16	
17	export class HybridBackend implements MemoryBackend {
18	  private sqliteBackend: SQLiteBackend;
19	  private agentDbBackend: AgentDBBackend;
20	  private initialized: boolean = false;
21	
22	  constructor(sqliteBackend: SQLiteBackend, agentDbBackend: AgentDBBackend) {
23	    this.sqliteBackend = sqliteBackend;
24	    this.agentDbBackend = agentDbBackend;
25	  }
26	
27	  /**
28	   * Initialize both backends
29	   */
30	  async initialize(): Promise<void> {
31	    if (this.initialized) return;
32	
33	    await Promise.all([
34	      this.sqliteBackend.initialize(),
35	      this.agentDbBackend.initialize()
36	    ]);
37	
38	    this.initialized = true;
39	  }
40	
41	  /**
42	   * Close both backends
43	   */
44	  async close(): Promise<void> {
45	    await Promise.all([
46	      this.sqliteBackend.close(),
47	      this.agentDbBackend.close()
48	    ]);
49	    this.initialized = false;
50	  }
51	
52	  /**
53	   * Store memory in both backends
54	   */
55	  async store(memory: Memory): Promise<Memory> {
56	    // Store in SQLite for structured queries
57	    await this.sqliteBackend.store(memory);
58	
59	    // Store in AgentDB if has embedding
60	    if (memory.embedding && memory.embedding.length > 0) {
61	      await this.agentDbBackend.store(memory);
62	    }
63	
64	    return memory;
65	  }
66	
67	  /**
68	   * Retrieve memory by ID (from SQLite primary)
69	   */
70	  async retrieve(id: string): Promise<Memory | undefined> {
71	    return this.sqliteBackend.retrieve(id);
72	  }
73	
74	  /**
75	   * Update memory in both backends
76	   */
77	  async update(memory: Memory): Promise<void> {
78	    await this.sqliteBackend.update(memory);
79	
80	    if (memory.embedding && memory.embedding.length > 0) {
81	      await this.agentDbBackend.update(memory);
82	    }
83	  }
84	
85	  /**
86	   * Delete memory from both backends
87	   */
88	  async delete(id: string): Promise<void> {
89	    await Promise.all([
90	      this.sqliteBackend.delete(id),
91	      this.agentDbBackend.delete(id)
92	    ]);
93	  }
94	
95	  /**
96	   * Query memories using SQLite
97	   */
98	  async query(query: MemoryQuery): Promise<Memory[]> {
99	    return this.sqliteBackend.query(query);
100	  }
101	
102	  /**
103	   * Vector search using AgentDB (150x-12,500x faster with HNSW)
104	   */
105	  async vectorSearch(embedding: number[], k: number = 10): Promise<MemorySearchResult[]> {
106	    return this.agentDbBackend.vectorSearch(embedding, k);
107	  }
108	
109	  /**
110	   * Clear all memories for an agent
111	   */
112	  async clearAgent(agentId: string): Promise<void> {
113	    await Promise.all([
114	      this.sqliteBackend.clearAgent(agentId),
115	      this.agentDbBackend.clearAgent(agentId)
116	    ]);
117	  }
118	
119	  /**
120	   * Hybrid search: combine SQL filtering with vector similarity
121	   */
122	  async hybridSearch(
123	    query: MemoryQuery,
124	    embedding?: number[],
125	    k: number = 10
126	  ): Promise<MemorySearchResult[]> {
127	    if (!embedding) {
128	      // No embedding, fall back to SQL query
129	      const results = await this.query(query);
130	      return results.map(m => ({ ...m, similarity: 1.0 }));
131	    }
132	
133	    // Get vector search results
134	    const vectorResults = await this.vectorSearch(embedding, k * 2);
135	
136	    // Filter by query criteria
137	    let filtered = vectorResults;
138	
139	    if (query.agentId) {
140	      filtered = filtered.filter(m => m.agentId === query.agentId);
141	    }
142	    if (query.type) {
143	      filtered = filtered.filter(m => m.type === query.type);
144	    }
145	    if (query.timeRange) {
146	      filtered = filtered.filter(
147	        m => m.timestamp >= query.timeRange!.start && m.timestamp <= query.timeRange!.end
148	      );
149	    }
150	    if (query.metadata) {
151	      filtered = filtered.filter(m => {
152	        if (!m.metadata) return false;
153	        return Object.entries(query.metadata!).every(
154	          ([key, value]) => m.metadata![key] === value
155	        );
156	      });
157	    }
158	
159	    return filtered.slice(0, k);
160	  }
161	
162	  /**
163	   * Get backend statistics
164	   */
165	  getStats(): { sqlite: number; agentdb: number } {
166	    return {
167	      sqlite: this.sqliteBackend.getCount(),
168	      agentdb: 0 // AgentDB doesn't expose count directly
169	    };
170	  }
171	}
172	
173	export { HybridBackend as default };
174

1	/**
2	 * Task Domain Entity
3	 *
4	 * Represents a task to be executed by agents in the V3 system
5	 */
6	
7	import type {
8	  Task as ITask,
9	  TaskPriority,
10	  TaskStatus,
11	  TaskType,
12	  WorkflowDefinition
13	} from '../../shared/types';
14	
15	export class Task implements ITask {
16	  public readonly id: string;
17	  public readonly type: TaskType;
18	  public description: string;
19	  public priority: TaskPriority;
20	  public status: TaskStatus;
21	  public assignedTo?: string;
22	  public dependencies: string[];
23	  public metadata?: Record<string, unknown>;
24	  public workflow?: WorkflowDefinition;
25	  public onExecute?: () => void | Promise<void>;
26	  public onRollback?: () => void | Promise<void>;
27	
28	  private startedAt?: number;
29	  private completedAt?: number;
30	
31	  constructor(config: ITask) {
32	    this.id = config.id;
33	    this.type = config.type;
34	    this.description = config.description;
35	    this.priority = config.priority;
36	    this.status = config.status || 'pending';
37	    this.assignedTo = config.assignedTo;
38	    this.dependencies = config.dependencies || [];
39	    this.metadata = config.metadata || {};
40	    this.workflow = config.workflow;
41	    this.onExecute = config.onExecute;
42	    this.onRollback = config.onRollback;
43	  }
44	
45	  /**
46	   * Check if task has all dependencies resolved
47	   */
48	  areDependenciesResolved(completedTasks: Set<string>): boolean {
49	    return this.dependencies.every(dep => completedTasks.has(dep));
50	  }
51	
52	  /**
53	   * Mark task as started
54	   */
55	  start(): void {
56	    if (this.status === 'pending') {
57	      this.status = 'in-progress';
58	      this.startedAt = Date.now();
59	    }
60	  }
61	
62	  /**
63	   * Mark task as completed
64	   */
65	  complete(): void {
66	    if (this.status === 'in-progress') {
67	      this.status = 'completed';
68	      this.completedAt = Date.now();
69	    }
70	  }
71	
72	  /**
73	   * Mark task as failed
74	   */
75	  fail(error?: string): void {
76	    this.status = 'failed';
77	    this.completedAt = Date.now();
78	    if (error && this.metadata) {
79	      this.metadata.error = error;
80	    }
81	  }
82	
83	  /**
84	   * Cancel the task
85	   */
86	  cancel(): void {
87	    if (this.status !== 'completed' && this.status !== 'failed') {
88	      this.status = 'cancelled';
89	      this.completedAt = Date.now();
90	    }
91	  }
92	
93	  /**
94	   * Get task duration
95	   */
96	  getDuration(): number | undefined {
97	    if (this.startedAt && this.completedAt) {
98	      return this.completedAt - this.startedAt;
99	    }
100	    if (this.startedAt) {
101	      return Date.now() - this.startedAt;
102	    }
103	    return undefined;
104	  }
105	
106	  /**
107	   * Check if task is a nested workflow
108	   */
109	  isWorkflow(): boolean {
110	    return this.type === 'workflow' && this.workflow !== undefined;
111	  }
112	
113	  /**
114	   * Assign task to an agent
115	   */
116	  assignTo(agentId: string): void {
117	    this.assignedTo = agentId;
118	  }
119	
120	  /**
121	   * Get priority as numeric value for sorting
122	   */
123	  getPriorityValue(): number {
124	    const values: Record<TaskPriority, number> = {
125	      high: 3,
126	      medium: 2,
127	      low: 1
128	    };
129	    return values[this.priority] || 2;
130	  }
131	
132	  /**
133	   * Convert to plain object for serialization
134	   */
135	  toJSON(): ITask {
136	    return {
137	      id: this.id,
138	      type: this.type,
139	      description: this.description,
140	      priority: this.priority,
141	      status: this.status,
142	      assignedTo: this.assignedTo,
143	      dependencies: this.dependencies,
144	      metadata: {
145	        ...this.metadata,
146	        startedAt: this.startedAt,
147	        completedAt: this.completedAt,
148	        duration: this.getDuration()
149	      },
150	      workflow: this.workflow
151	    };
152	  }
153	
154	  /**
155	   * Create task from config
156	   */
157	  static fromConfig(config: ITask): Task {
158	    return new Task(config);
159	  }
160	
161	  /**
162	   * Sort tasks by priority (high to low)
163	   */
164	  static sortByPriority(tasks: Task[]): Task[] {
165	    return [...tasks].sort((a, b) => b.getPriorityValue() - a.getPriorityValue());
166	  }
167	
168	  /**
169	   * Resolve task execution order based on dependencies
170	   */
171	  static resolveExecutionOrder(tasks: Task[]): Task[] {
172	    const resolved: Task[] = [];
173	    const resolvedIds = new Set<string>();
174	    const remaining = [...tasks];
175	
176	    // Topological sort
177	    while (remaining.length > 0) {
178	      const ready = remaining.filter(task =>
179	        task.areDependenciesResolved(resolvedIds)
180	      );
181	
182	      if (ready.length === 0 && remaining.length > 0) {
183	        throw new Error('Circular dependency detected in tasks');
184	      }
185	
186	      // Sort ready tasks by priority
187	      const sorted = Task.sortByPriority(ready);
188	
189	      for (const task of sorted) {
190	        resolved.push(task);
191	        resolvedIds.add(task.id);
192	        const index = remaining.indexOf(task);
193	        if (index > -1) {
194	          remaining.splice(index, 1);
195	        }
196	      }
197	    }
198	
199	    return resolved;
200	  }
201	}
202	
203	export { Task as default };
204

