1	/**
2	 * Agent Domain Entity
3	 *
4	 * Represents an AI agent in the V3 system
5	 */
6	
7	import type {
8	  Agent as IAgent,
9	  AgentConfig,
10	  AgentStatus,
11	  AgentType,
12	  AgentRole,
13	  Task,
14	  TaskResult
15	} from '../../shared/types';
16	
17	export class Agent implements IAgent {
18	  public readonly id: string;
19	  public readonly type: AgentType;
20	  public status: AgentStatus;
21	  public capabilities: string[];
22	  public role?: AgentRole;
23	  public parent?: string;
24	  public metadata?: Record<string, unknown>;
25	  public createdAt: number;
26	  public lastActive: number;
27	
28	  constructor(config: AgentConfig) {
29	    this.id = config.id;
30	    this.type = config.type;
31	    this.status = 'active';
32	    this.capabilities = config.capabilities || [];
33	    this.role = config.role;
34	    this.parent = config.parent;
35	    this.metadata = config.metadata || {};
36	    this.createdAt = Date.now();
37	    this.lastActive = Date.now();
38	  }
39	
40	  /**
41	   * Execute a task assigned to this agent
42	   */
43	  async executeTask(task: Task): Promise<TaskResult> {
44	    if (this.status !== 'active' && this.status !== 'idle') {
45	      return {
46	        taskId: task.id,
47	        status: 'failed',
48	        error: `Agent ${this.id} is not available (status: ${this.status})`,
49	        agentId: this.id
50	      };
51	    }
52	
53	    const startTime = Date.now();
54	    this.status = 'busy';
55	    this.lastActive = startTime;
56	
57	    try {
58	      // Execute task-specific callback if provided
59	      if (task.onExecute) {
60	        await task.onExecute();
61	      }
62	
63	      // Process task with minimal overhead (actual work done via onExecute callback)
64	      await this.processTaskExecution(task);
65	
66	      const duration = Date.now() - startTime;
67	      this.status = 'active';
68	      this.lastActive = Date.now();
69	
70	      return {
71	        taskId: task.id,
72	        status: 'completed',
73	        result: `Task ${task.id} completed successfully`,
74	        duration,
75	        agentId: this.id
76	      };
77	    } catch (error) {
78	      const duration = Date.now() - startTime;
79	      this.status = 'active';
80	
81	      return {
82	        taskId: task.id,
83	        status: 'failed',
84	        error: error instanceof Error ? error.message : String(error),
85	        duration,
86	        agentId: this.id
87	      };
88	    }
89	  }
90	
91	  /**
92	   * Execute task processing with priority-based timing
93	   * In production, the actual work is done via task.onExecute() callback
94	   * This method provides minimal overhead processing time
95	   */
96	  private async processTaskExecution(task: Task): Promise<void> {
97	    // Minimal processing overhead based on priority
98	    // Actual task work is performed by onExecute callback
99	    const processingTime: Record<string, number> = {
100	      high: 1,
101	      medium: 5,
102	      low: 10
103	    };
104	    const overhead = processingTime[task.priority] || 5;
105	    await new Promise(resolve => setTimeout(resolve, overhead));
106	  }
107	
108	  /**
109	   * Check if agent has a specific capability
110	   */
111	  hasCapability(capability: string): boolean {
112	    return this.capabilities.includes(capability);
113	  }
114	
115	  /**
116	   * Check if agent can execute a task type
117	   */
118	  canExecute(taskType: string): boolean {
119	    const typeToCapability: Record<string, string> = {
120	      code: 'code',
121	      test: 'test',
122	      review: 'review',
123	      design: 'design',
124	      deploy: 'deploy',
125	      refactor: 'refactor',
126	      debug: 'debug'
127	    };
128	
129	    const requiredCapability = typeToCapability[taskType];
130	    return requiredCapability ? this.hasCapability(requiredCapability) : true;
131	  }
132	
133	  /**
134	   * Terminate the agent
135	   */
136	  terminate(): void {
137	    this.status = 'terminated';
138	    this.lastActive = Date.now();
139	  }
140	
141	  /**
142	   * Mark agent as idle
143	   */
144	  setIdle(): void {
145	    if (this.status === 'active' || this.status === 'busy') {
146	      this.status = 'idle';
147	      this.lastActive = Date.now();
148	    }
149	  }
150	
151	  /**
