1	/**
2	 * V3 MCP Connection Pool Manager
3	 *
4	 * High-performance connection pooling for MCP server:
5	 * - Reusable connections to reduce overhead
6	 * - Max connections: 10 (configurable)
7	 * - Idle timeout handling with automatic eviction
8	 * - Connection health monitoring
9	 * - Graceful shutdown support
10	 *
11	 * Performance Targets:
12	 * - Connection acquire: <5ms
13	 * - Connection release: <1ms
14	 */
15	
16	import { EventEmitter } from 'events';
17	import {
18	  PooledConnection,
19	  ConnectionPoolStats,
20	  ConnectionPoolConfig,
21	  ConnectionState,
22	  IConnectionPool,
23	  ILogger,
24	  TransportType,
25	} from './types.js';
26	
27	/**
28	 * Default connection pool configuration
29	 */
30	const DEFAULT_POOL_CONFIG: ConnectionPoolConfig = {
31	  maxConnections: 10,
32	  minConnections: 2,
33	  idleTimeout: 30000, // 30 seconds
34	  acquireTimeout: 5000, // 5 seconds
35	  maxWaitingClients: 50,
36	  evictionRunInterval: 10000, // 10 seconds
37	};
38	
39	/**
40	 * Connection wrapper with lifecycle management
41	 */
42	class ManagedConnection implements PooledConnection {
43	  public state: ConnectionState = 'idle';
44	  public lastUsedAt: Date;
45	  public useCount: number = 0;
46	
47	  constructor(
48	    public readonly id: string,
49	    public readonly transport: TransportType,
50	    public readonly createdAt: Date = new Date(),
51	    public metadata?: Record<string, unknown>
52	  ) {
53	    this.lastUsedAt = this.createdAt;
54	  }
55	
56	  /**
57	   * Mark connection as busy
58	   */
59	  acquire(): void {
60	    this.state = 'busy';
61	    this.lastUsedAt = new Date();
62	    this.useCount++;
63	  }
64	
65	  /**
66	   * Mark connection as idle
67	   */
68	  release(): void {
69	    this.state = 'idle';
70	    this.lastUsedAt = new Date();
71	  }
72	
73	  /**
74	   * Check if connection is expired
75	   */
76	  isExpired(idleTimeout: number): boolean {
77	    if (this.state !== 'idle') return false;
78	    return Date.now() - this.lastUsedAt.getTime() > idleTimeout;
79	  }
80	
81	  /**
82	   * Check if connection is healthy
83	   */
84	  isHealthy(): boolean {
85	    return this.state !== 'error' && this.state !== 'closed';
86	  }
87	}
88	
89	/**
90	 * Waiting client for connection
91	 */
92	interface WaitingClient {
93	  resolve: (connection: PooledConnection) => void;
94	  reject: (error: Error) => void;
95	  timestamp: number;
96	}
97	
98	/**
99	 * Connection Pool Manager
100	 *
101	 * Manages a pool of reusable connections for optimal performance
102	 */
103	export class ConnectionPool extends EventEmitter implements IConnectionPool {
104	  private readonly config: ConnectionPoolConfig;
105	  private readonly connections: Map<string, ManagedConnection> = new Map();
106	  private readonly waitingClients: WaitingClient[] = [];
107	  private evictionTimer?: NodeJS.Timeout;
108	  private connectionCounter: number = 0;
109	  private isShuttingDown: boolean = false;
110	
111	  // Statistics
112	  private stats = {
113	    totalAcquired: 0,
114	    totalReleased: 0,
115	    totalCreated: 0,
116	    totalDestroyed: 0,
117	    acquireTimeTotal: 0,
118	    acquireCount: 0,
119	  };
120	
121	  constructor(
122	    config: Partial<ConnectionPoolConfig> = {},
123	    private readonly logger: ILogger,
124	    private readonly transportType: TransportType = 'in-process'
125	  ) {
126	    super();
127	    this.config = { ...DEFAULT_POOL_CONFIG, ...config };
128	    this.startEvictionTimer();
129	    this.initializeMinConnections();
130	  }
131	
132	  /**
133	   * Initialize minimum number of connections
134	   */
135	  private async initializeMinConnections(): Promise<void> {
136	    const promises: Promise<void>[] = [];
137	    for (let i = 0; i < this.config.minConnections; i++) {
138	      promises.push(this.createConnection());
139	    }
140	    await Promise.all(promises);
141	    this.logger.debug('Connection pool initialized', {
142	      minConnections: this.config.minConnections,
143	    });
144	  }
145	
146	  /**
147	   * Create a new connection
148	   */
149	  private async createConnection(): Promise<ManagedConnection> {
150	    const id = `conn-${++this.connectionCounter}-${Date.now()}`;
151	    const connection = new ManagedConnection(id, this.transportType);
152	
153	    this.connections.set(id, connection);
154	    this.stats.totalCreated++;
155	
156	    this.emit('pool:connection:created', { connectionId: id });
157	    this.logger.debug('Connection created', { id, total: this.connections.size });
158	
159	    return connection;
160	  }
161	
162	  /**
163	   * Acquire a connection from the pool
164	   */
165	  async acquire(): Promise<PooledConnection> {
166	    const startTime = performance.now();
167	
168	    if (this.isShuttingDown) {
169	      throw new Error('Connection pool is shutting down');
170	    }
171	
172	    // Try to find an idle connection
173	    for (const connection of this.connections.values()) {
174	      if (connection.state === 'idle' && connection.isHealthy()) {
175	        connection.acquire();
176	        this.stats.totalAcquired++;
177	        this.recordAcquireTime(startTime);
178	
179	        this.emit('pool:connection:acquired', { connectionId: connection.id });
180	        this.logger.debug('Connection acquired from pool', { id: connection.id });
181	
182	        return connection;
183	      }
184	    }
185	
186	    // Create new connection if under limit
187	    if (this.connections.size < this.config.maxConnections) {
188	      const connection = await this.createConnection();
189	      connection.acquire();
190	      this.stats.totalAcquired++;
191	      this.recordAcquireTime(startTime);
192	
193	      this.emit('pool:connection:acquired', { connectionId: connection.id });
194	      return connection;
195	    }
196	
197	    // Wait for a connection to become available
198	    return this.waitForConnection(startTime);
199	  }
200	
201	  /**
202	   * Wait for a connection to become available
203	   */
204	  private waitForConnection(startTime: number): Promise<PooledConnection> {
205	    return new Promise((resolve, reject) => {
206	      if (this.waitingClients.length >= this.config.maxWaitingClients) {
207	        reject(new Error('Connection pool exhausted - max waiting clients reached'));
208	        return;
209	      }
210	
211	      const client: WaitingClient = {
212	        resolve: (connection) => {
213	          this.recordAcquireTime(startTime);
214	          resolve(connection);
215	        },
216	        reject,
217	        timestamp: Date.now(),
218	      };
219	
220	      this.waitingClients.push(client);
221	
222	      // Set timeout
223	      setTimeout(() => {
224	        const index = this.waitingClients.indexOf(client);
225	        if (index !== -1) {
226	          this.waitingClients.splice(index, 1);
227	          reject(new Error(`Connection acquire timeout after ${this.config.acquireTimeout}ms`));
228	        }
229	      }, this.config.acquireTimeout);
230	    });
231	  }
232	
233	  /**
234	   * Release a connection back to the pool
235	   */
236	  release(connection: PooledConnection): void {
237	    const managed = this.connections.get(connection.id);
238	    if (!managed) {
239	      this.logger.warn('Attempted to release unknown connection', { id: connection.id });
240	      return;
241	    }
242	
243	    // Check for waiting clients first
244	    const waitingClient = this.waitingClients.shift();
245	    if (waitingClient) {
246	      managed.acquire();
247	      this.stats.totalAcquired++;
248	      this.emit('pool:connection:acquired', { connectionId: connection.id });
249	      waitingClient.resolve(managed);
250	      return;
251	    }
252	
253	    // Return to pool
254	    managed.release();
255	    this.stats.totalReleased++;
256	
257	    this.emit('pool:connection:released', { connectionId: connection.id });
258	    this.logger.debug('Connection released to pool', { id: connection.id });
259	  }
260	
261	  /**
262	   * Destroy a connection (remove from pool)
263	   */
264	  destroy(connection: PooledConnection): void {
265	    const managed = this.connections.get(connection.id);
266	    if (!managed) {
267	      return;
268	    }
269	
270	    managed.state = 'closed';
271	    this.connections.delete(connection.id);
272	    this.stats.totalDestroyed++;
273	
274	    this.emit('pool:connection:destroyed', { connectionId: connection.id });
275	    this.logger.debug('Connection destroyed', { id: connection.id });
276	
277	    // Create new connection to maintain minimum if needed
278	    if (this.connections.size < this.config.minConnections && !this.isShuttingDown) {
279	      this.createConnection().catch((err) => {
280	        this.logger.error('Failed to create replacement connection', err);
281	      });
282	    }
283	  }
284	
285	  /**
286	   * Get pool statistics
287	   */
288	  getStats(): ConnectionPoolStats {
289	    let idleCount = 0;
290	    let busyCount = 0;
291	
292	    for (const connection of this.connections.values()) {
293	      if (connection.state === 'idle') idleCount++;
294	      else if (connection.state === 'busy') busyCount++;
295	    }
296	
297	    return {
298	      totalConnections: this.connections.size,
299	      idleConnections: idleCount,
300	      busyConnections: busyCount,
301	      pendingRequests: this.waitingClients.length,
302	      totalAcquired: this.stats.totalAcquired,
303	      totalReleased: this.stats.totalReleased,
304	      totalCreated: this.stats.totalCreated,
305	      totalDestroyed: this.stats.totalDestroyed,
306	      avgAcquireTime: this.stats.acquireCount > 0
307	        ? this.stats.acquireTimeTotal / this.stats.acquireCount
308	        : 0,
309	    };
310	  }
311	
312	  /**
313	   * Drain the pool (wait for all connections to be released)
314	   */
315	  async drain(): Promise<void> {
316	    this.isShuttingDown = true;
317	    this.logger.info('Draining connection pool');
318	
319	    // Reject all waiting clients
320	    while (this.waitingClients.length > 0) {
321	      const client = this.waitingClients.shift();
322	      client?.reject(new Error('Connection pool is draining'));
323	    }
324	
325	    // Wait for busy connections to be released
326	    const maxWait = 10000; // 10 seconds
327	    const startTime = Date.now();
328	
329	    while (Date.now() - startTime < maxWait) {
330	      let busyCount = 0;
331	      for (const connection of this.connections.values()) {
332	        if (connection.state === 'busy') busyCount++;
333	      }
334	
335	      if (busyCount === 0) break;
336	
337	      await new Promise((resolve) => setTimeout(resolve, 100));
338	    }
339	
340	    this.logger.info('Connection pool drained');
341	  }
342	
343	  /**
344	   * Clear all connections from the pool
345	   */
346	  async clear(): Promise<void> {
347	    this.stopEvictionTimer();
348	    await this.drain();
349	
350	    // Destroy all remaining connections
351	    for (const connection of this.connections.values()) {
352	      connection.state = 'closed';
353	    }
354	
355	    this.connections.clear();
356	    this.logger.info('Connection pool cleared');
357	  }
358	
359	  /**
360	   * Start the eviction timer
361	   */
362	  private startEvictionTimer(): void {
363	    this.evictionTimer = setInterval(() => {
364	      this.evictIdleConnections();
365	    }, this.config.evictionRunInterval);
366	  }
367	
368	  /**
369	   * Stop the eviction timer
370	   */
371	  private stopEvictionTimer(): void {
372	    if (this.evictionTimer) {
373	      clearInterval(this.evictionTimer);
374	      this.evictionTimer = undefined;
375	    }
376	  }
377	
378	  /**
379	   * Evict idle connections that have exceeded the timeout
380	   */
381	  private evictIdleConnections(): void {
382	    if (this.isShuttingDown) return;
383	
384	    const toEvict: ManagedConnection[] = [];
385	
386	    for (const connection of this.connections.values()) {
387	      if (
388	        connection.isExpired(this.config.idleTimeout) &&
389	        this.connections.size > this.config.minConnections
390	      ) {
391	        toEvict.push(connection);
392	      }
393	    }
394	
395	    for (const connection of toEvict) {
396	      this.destroy(connection);
397	      this.logger.debug('Evicted idle connection', { id: connection.id });
398	    }
399	
400	    if (toEvict.length > 0) {
401	      this.logger.info('Evicted idle connections', { count: toEvict.length });
402	    }
403	  }
404	
405	  /**
406	   * Record acquire time for statistics
407	   */
408	  private recordAcquireTime(startTime: number): void {
409	    const duration = performance.now() - startTime;
410	    this.stats.acquireTimeTotal += duration;
411	    this.stats.acquireCount++;
412	  }
413	
414	  /**
415	   * Get all connections (for debugging/monitoring)
416	   */
417	  getConnections(): PooledConnection[] {
418	    return Array.from(this.connections.values());
419	  }
420	
421	  /**
422	   * Check if pool is healthy
423	   */
424	  isHealthy(): boolean {
425	    return !this.isShuttingDown && this.connections.size >= this.config.minConnections;
426	  }
427	}
428	
429	/**
430	 * Create a connection pool with default settings
431	 */
432	export function createConnectionPool(
433	  config: Partial<ConnectionPoolConfig> = {},
434	  logger: ILogger,
435	  transportType: TransportType = 'in-process'
436	): ConnectionPool {
437	  return new ConnectionPool(config, logger, transportType);
438	}
