1	/**
2	 * V3 MCP Tool Registry
3	 *
4	 * High-performance tool management with:
5	 * - Fast O(1) lookup using Map
6	 * - Category-based organization
7	 * - Tool validation on registration
8	 * - Dynamic registration/unregistration
9	 * - Caching for frequently used tools
10	 *
11	 * Performance Targets:
12	 * - Tool registration: <10ms
13	 * - Tool lookup: <1ms
14	 * - Tool validation: <5ms
15	 */
16	
17	import { EventEmitter } from 'events';
18	import Ajv from 'ajv';
19	import {
20	  MCPTool,
21	  JSONSchema,
22	  ToolHandler,
23	  ToolContext,
24	  ToolCallResult,
25	  ToolRegistrationOptions,
26	  ILogger,
27	} from './types.js';
28	
29	// Schema validator instance (singleton for performance)
30	const ajv = new Ajv({ allErrors: true, strict: false });
31	
32	/**
33	 * Tool metadata for enhanced lookup
34	 */
35	interface ToolMetadata {
36	  tool: MCPTool;
37	  registeredAt: Date;
38	  callCount: number;
39	  lastCalled?: Date;
40	  avgExecutionTime: number;
41	  errorCount: number;
42	}
43	
44	/**
45	 * Tool search options
46	 */
47	interface ToolSearchOptions {
48	  category?: string;
49	  tags?: string[];
50	  deprecated?: boolean;
51	  cacheable?: boolean;
52	}
53	
54	/**
55	 * Tool Registry
56	 *
57	 * Manages registration, lookup, and execution of MCP tools
58	 */
59	export class ToolRegistry extends EventEmitter {
60	  private readonly tools: Map<string, ToolMetadata> = new Map();
61	  private readonly categoryIndex: Map<string, Set<string>> = new Map();
62	  private readonly tagIndex: Map<string, Set<string>> = new Map();
63	  private defaultContext?: ToolContext;
64	
65	  // Performance tracking
66	  private totalRegistrations = 0;
67	  private totalLookups = 0;
68	  private totalExecutions = 0;
69	
70	  constructor(private readonly logger: ILogger) {
71	    super();
72	  }
73	
74	  /**
75	   * Register a tool
76	   */
77	  register(tool: MCPTool, options: ToolRegistrationOptions = {}): boolean {
78	    const startTime = performance.now();
79	
80	    // Check for existing tool
81	    if (this.tools.has(tool.name) && !options.override) {
82	      this.logger.warn('Tool already registered', { name: tool.name });
83	      return false;
84	    }
85	
86	    // Validate tool if requested
87	    if (options.validate !== false) {
88	      const validation = this.validateTool(tool);
89	      if (!validation.valid) {
90	        this.logger.error('Tool validation failed', {
91	          name: tool.name,
92	          errors: validation.errors,
93	        });
94	        return false;
95	      }
96	    }
97	
98	    // Create metadata
99	    const metadata: ToolMetadata = {
100	      tool,
101	      registeredAt: new Date(),
102	      callCount: 0,
103	      avgExecutionTime: 0,
104	      errorCount: 0,
105	    };
106	
107	    // Register tool
108	    this.tools.set(tool.name, metadata);
109	    this.totalRegistrations++;
110	
111	    // Update category index
112	    if (tool.category) {
113	      if (!this.categoryIndex.has(tool.category)) {
114	        this.categoryIndex.set(tool.category, new Set());
115	      }
116	      this.categoryIndex.get(tool.category)!.add(tool.name);
117	    }
118	
119	    // Update tag index
120	    if (tool.tags) {
121	      for (const tag of tool.tags) {
122	        if (!this.tagIndex.has(tag)) {
123	          this.tagIndex.set(tag, new Set());
124	        }
125	        this.tagIndex.get(tag)!.add(tool.name);
126	      }
127	    }
128	
129	    const duration = performance.now() - startTime;
130	    this.logger.debug('Tool registered', {
131	      name: tool.name,
132	      category: tool.category,
133	      duration: `${duration.toFixed(2)}ms`,
134	    });
135	
136	    this.emit('tool:registered', tool.name);
137	    return true;
138	  }
139	
140	  /**
141	   * Register multiple tools at once
142	   */
143	  registerBatch(tools: MCPTool[], options: ToolRegistrationOptions = {}): {
144	    registered: number;
145	    failed: string[];
146	  } {
147	    const startTime = performance.now();
148	    const failed: string[] = [];
149	    let registered = 0;
150	
151	    for (const tool of tools) {
152	      if (this.register(tool, options)) {
153	        registered++;
154	      } else {
155	        failed.push(tool.name);
156	      }
157	    }
158	
159	    const duration = performance.now() - startTime;
160	    this.logger.info('Batch registration complete', {
161	      total: tools.length,
162	      registered,
163	      failed: failed.length,
164	      duration: `${duration.toFixed(2)}ms`,
165	    });
166	
167	    return { registered, failed };
168	  }
169	
170	  /**
171	   * Unregister a tool
172	   */
173	  unregister(name: string): boolean {
174	    const metadata = this.tools.get(name);
175	    if (!metadata) {
176	      return false;
177	    }
178	
179	    // Remove from category index
180	    if (metadata.tool.category) {
181	      const categoryTools = this.categoryIndex.get(metadata.tool.category);
182	      categoryTools?.delete(name);
183	      if (categoryTools?.size === 0) {
184	        this.categoryIndex.delete(metadata.tool.category);
185	      }
186	    }
187	
188	    // Remove from tag index
189	    if (metadata.tool.tags) {
190	      for (const tag of metadata.tool.tags) {
191	        const tagTools = this.tagIndex.get(tag);
192	        tagTools?.delete(name);
193	        if (tagTools?.size === 0) {
194	          this.tagIndex.delete(tag);
195	        }
196	      }
197	    }
198	
199	    this.tools.delete(name);
200	    this.logger.debug('Tool unregistered', { name });
201	    this.emit('tool:unregistered', name);
202	
203	    return true;
204	  }
205	
206	  /**
207	   * Get a tool by name
208	   */
209	  getTool(name: string): MCPTool | undefined {
210	    this.totalLookups++;
211	    return this.tools.get(name)?.tool;
212	  }
213	
214	  /**
215	   * Check if a tool exists
216	   */
217	  hasTool(name: string): boolean {
218	    return this.tools.has(name);
219	  }
220	
221	  /**
222	   * Get tool count
223	   */
224	  getToolCount(): number {
225	    return this.tools.size;
226	  }
227	
228	  /**
229	   * Get all tool names
230	   */
231	  getToolNames(): string[] {
232	    return Array.from(this.tools.keys());
233	  }
234	
235	  /**
236	   * List all tools with metadata
237	   */
238	  listTools(): Array<{
239	    name: string;
240	    description: string;
241	    category?: string;
242	    tags?: string[];
243	    deprecated?: boolean;
244	  }> {
245	    return Array.from(this.tools.values()).map(({ tool }) => ({
246	      name: tool.name,
247	      description: tool.description,
248	      category: tool.category,
249	      tags: tool.tags,
250	      deprecated: tool.deprecated,
251	    }));
252	  }
253	
254	  /**
255	   * Search tools by criteria
256	   */
257	  search(options: ToolSearchOptions): MCPTool[] {
258	    let results: Set<string> | undefined;
259	
260	    // Filter by category
261	    if (options.category) {
262	      const categoryTools = this.categoryIndex.get(options.category);
263	      if (!categoryTools) return [];
264	      results = new Set(categoryTools);
265	    }
266	
267	    // Filter by tags (intersection)
268	    if (options.tags && options.tags.length > 0) {
269	      for (const tag of options.tags) {
270	        const tagTools = this.tagIndex.get(tag);
271	        if (!tagTools) return [];
272	
273	        if (results) {
274	          results = new Set([...results].filter((name) => tagTools.has(name)));
275	        } else {
276	          results = new Set(tagTools);
277	        }
278	      }
279	    }
280	
281	    // Get all tools if no filters applied
282	    if (!results) {
283	      results = new Set(this.tools.keys());
284	    }
285	
286	    // Convert to tools and apply additional filters
287	    const tools: MCPTool[] = [];
288	    for (const name of results) {
289	      const metadata = this.tools.get(name);
290	      if (!metadata) continue;
291	
292	      const tool = metadata.tool;
293	
294	      // Filter by deprecated status
295	      if (options.deprecated !== undefined && tool.deprecated !== options.deprecated) {
296	        continue;
297	      }
298	
299	      // Filter by cacheable status
300	      if (options.cacheable !== undefined && tool.cacheable !== options.cacheable) {
301	        continue;
302	      }
303	
304	      tools.push(tool);
305	    }
306	
307	    return tools;
308	  }
309	
310	  /**
311	   * Get tools by category
312	   */
313	  getByCategory(category: string): MCPTool[] {
314	    const toolNames = this.categoryIndex.get(category);
315	    if (!toolNames) return [];
316	
317	    return Array.from(toolNames)
318	      .map((name) => this.tools.get(name)?.tool)
319	      .filter((tool): tool is MCPTool => tool !== undefined);
320	  }
321	
322	  /**
323	   * Get tools by tag
324	   */
325	  getByTag(tag: string): MCPTool[] {
326	    const toolNames = this.tagIndex.get(tag);
327	    if (!toolNames) return [];
328	
329	    return Array.from(toolNames)
330	      .map((name) => this.tools.get(name)?.tool)
331	      .filter((tool): tool is MCPTool => tool !== undefined);
332	  }
333	
334	  /**
335	   * Get all categories
336	   */
337	  getCategories(): string[] {
338	    return Array.from(this.categoryIndex.keys());
339	  }
340	
341	  /**
342	   * Get all tags
343	   */
344	  getTags(): string[] {
345	    return Array.from(this.tagIndex.keys());
346	  }
347	
348	  /**
349	   * Validate input against schema
350	   */
351	  private validateInput(input: Record<string, unknown>, schema: JSONSchema): { valid: boolean; errors?: string[] } {
352	    try {
353	      const validate = ajv.compile(schema);
354	      const valid = validate(input);
355	
356	      if (!valid && validate.errors) {
357	        return {
358	          valid: false,
359	          errors: validate.errors.map(e => `${e.instancePath || 'input'}: ${e.message}`),
360	        };
361	      }
362	
363	      return { valid: true };
364	    } catch (error) {
365	      return {
366	        valid: false,
367	        errors: [`Schema validation error: ${error instanceof Error ? error.message : String(error)}`],
368	      };
369	    }
370	  }
371	
372	  /**
373	   * Execute a tool
374	   */
375	  async execute(
376	    name: string,
377	    input: Record<string, unknown>,
378	    context?: ToolContext
379	  ): Promise<ToolCallResult> {
380	    const startTime = performance.now();
381	    const metadata = this.tools.get(name);
382	
383	    if (!metadata) {
384	      return {
385	        content: [{ type: 'text', text: `Tool not found: ${name}` }],
386	        isError: true,
387	      };
388	    }
389	
390	    // Validate input against schema before execution (security boundary)
391	    const validation = this.validateInput(input, metadata.tool.inputSchema);
392	    if (!validation.valid) {
393	      this.logger.warn('Tool input validation failed', {
394	        name,
395	        errors: validation.errors,
396	      });
397	      return {
398	        content: [{ type: 'text', text: `Input validation failed: ${validation.errors?.join(', ')}` }],
399	        isError: true,
400	      };
401	    }
402	
403	    const execContext = { ...this.defaultContext, ...context };
404	    this.totalExecutions++;
405	    metadata.callCount++;
406	    metadata.lastCalled = new Date();
407	
408	    try {
409	      this.emit('tool:called', { name, input });
410	
411	      const result = await metadata.tool.handler(input, execContext);
412	
413	      const duration = performance.now() - startTime;
414	      this.updateAverageExecutionTime(metadata, duration);
415	
416	      this.logger.debug('Tool executed', {
417	        name,
418	        duration: `${duration.toFixed(2)}ms`,
419	        success: true,
420	      });
421	
422	      this.emit('tool:completed', { name, duration, success: true });
423	
424	      // Format result
425	      return {
426	        content: [{
427	          type: 'text',
428	          text: typeof result === 'string' ? result : JSON.stringify(result, null, 2),
429	        }],
430	        isError: false,
431	      };
432	    } catch (error) {
433	      const duration = performance.now() - startTime;
434	      metadata.errorCount++;
435	
436	      this.logger.error('Tool execution failed', { name, error });
437	      this.emit('tool:error', { name, error, duration });
438	
439	      return {
440	        content: [{
441	          type: 'text',
442	          text: `Error: ${error instanceof Error ? error.message : String(error)}`,
443	        }],
444	        isError: true,
445	      };
446	    }
447	  }
448	
449	  /**
450	   * Set default execution context
451	   */
452	  setDefaultContext(context: ToolContext): void {
453	    this.defaultContext = context;
454	  }
455	
456	  /**
457	   * Get tool metadata
458	   */
459	  getMetadata(name: string): ToolMetadata | undefined {
460	    return this.tools.get(name);
461	  }
462	
463	  /**
464	   * Get registry statistics
465	   */
466	  getStats(): {
467	    totalTools: number;
468	    totalCategories: number;
469	    totalTags: number;
470	    totalRegistrations: number;
471	    totalLookups: number;
472	    totalExecutions: number;
473	    topTools: Array<{ name: string; calls: number }>;
474	  } {
475	    // Get top 10 most used tools
476	    const topTools = Array.from(this.tools.entries())
477	      .map(([name, metadata]) => ({ name, calls: metadata.callCount }))
478	      .sort((a, b) => b.calls - a.calls)
479	      .slice(0, 10);
480	
481	    return {
482	      totalTools: this.tools.size,
483	      totalCategories: this.categoryIndex.size,
484	      totalTags: this.tagIndex.size,
485	      totalRegistrations: this.totalRegistrations,
486	      totalLookups: this.totalLookups,
487	      totalExecutions: this.totalExecutions,
488	      topTools,
489	    };
490	  }
491	
492	  /**
493	   * Validate a tool definition
494	   */
495	  validateTool(tool: MCPTool): { valid: boolean; errors: string[] } {
496	    const errors: string[] = [];
497	
498	    if (!tool.name || typeof tool.name !== 'string') {
499	      errors.push('Tool name is required and must be a string');
500	    } else if (!/^[a-zA-Z][a-zA-Z0-9_/:-]*$/.test(tool.name)) {
501	      errors.push('Tool name must start with a letter and contain only alphanumeric characters, underscores, slashes, colons, and hyphens');
502	    }
503	
504	    if (!tool.description || typeof tool.description !== 'string') {
505	      errors.push('Tool description is required and must be a string');
506	    }
507	
508	    if (!tool.inputSchema || typeof tool.inputSchema !== 'object') {
509	      errors.push('Tool inputSchema is required and must be an object');
510	    } else {
511	      const schemaErrors = this.validateSchema(tool.inputSchema);
512	      errors.push(...schemaErrors);
513	    }
514	
515	    if (typeof tool.handler !== 'function') {
516	      errors.push('Tool handler is required and must be a function');
517	    }
518	
519	    return {
520	      valid: errors.length === 0,
521	      errors,
522	    };
523	  }
524	
525	  /**
526	   * Validate JSON Schema
527	   */
528	  private validateSchema(schema: JSONSchema, path = ''): string[] {
529	    const errors: string[] = [];
530	
531	    if (!schema.type) {
532	      errors.push(`${path || 'schema'}: type is required`);
533	    }
534	
535	    if (schema.type === 'object' && schema.properties) {
536	      for (const [key, propSchema] of Object.entries(schema.properties)) {
537	        const propPath = path ? `${path}.${key}` : key;
538	        errors.push(...this.validateSchema(propSchema, propPath));
539	      }
540	    }
541	
542	    if (schema.type === 'array' && schema.items) {
543	      errors.push(...this.validateSchema(schema.items, `${path}[]`));
544	    }
545	
546	    return errors;
547	  }
548	
549	  /**
550	   * Update average execution time
551	   */
552	  private updateAverageExecutionTime(metadata: ToolMetadata, duration: number): void {
553	    const n = metadata.callCount;
554	    metadata.avgExecutionTime =
555	      ((metadata.avgExecutionTime * (n - 1)) + duration) / n;
556	  }
557	
558	  /**
559	   * Clear all tools
560	   */
561	  clear(): void {
562	    this.tools.clear();
563	    this.categoryIndex.clear();
564	    this.tagIndex.clear();
565	    this.logger.info('Tool registry cleared');
566	    this.emit('registry:cleared');
567	  }
568	}
569	
570	/**
571	 * Create a tool registry
572	 */
573	export function createToolRegistry(logger: ILogger): ToolRegistry {
574	  return new ToolRegistry(logger);
575	}
576	
577	/**
578	 * Helper to create a tool definition
579	 */
580	export function defineTool<TInput = Record<string, unknown>, TOutput = unknown>(
581	  name: string,
582	  description: string,
583	  inputSchema: JSONSchema,
584	  handler: ToolHandler<TInput, TOutput>,
585	  options?: {
586	    category?: string;
587	    tags?: string[];
588	    version?: string;
589	    deprecated?: boolean;
590	    cacheable?: boolean;
591	    cacheTTL?: number;
592	    timeout?: number;
593	  }
594	): MCPTool<TInput, TOutput> {
595	  return {
596	    name,
597	    description,
598	    inputSchema,
599	    handler,
600	    ...options,
601	  };
602	}
