1	/**
2	 * Plugin Interface and Base Implementation
3	 *
4	 * Defines the plugin contract for V3 extensibility per ADR-004.
5	 */
6	
7	import type {
8	  Plugin as IPlugin,
9	  ExtensionPoint,
10	  PluginMetadata
11	} from '../../shared/types';
12	
13	export interface Plugin extends IPlugin {
14	  id: string;
15	  name: string;
16	  version: string;
17	  description?: string;
18	  author?: string;
19	  homepage?: string;
20	  priority?: number;
21	  dependencies?: string[];
22	  configSchema?: Record<string, unknown>;
23	  minCoreVersion?: string;
24	  maxCoreVersion?: string;
25	  initialize(config?: Record<string, unknown>): Promise<void>;
26	  shutdown(): Promise<void>;
27	  getExtensionPoints(): ExtensionPoint[];
28	}
29	
30	export { ExtensionPoint };
31	
32	/**
33	 * Abstract base class for plugins
34	 */
35	export abstract class BasePlugin implements Plugin {
36	  public readonly id: string;
37	  public readonly name: string;
38	  public readonly version: string;
39	  public description?: string;
40	  public author?: string;
41	  public homepage?: string;
42	  public priority?: number;
43	  public dependencies?: string[];
44	  public configSchema?: Record<string, unknown>;
45	  public minCoreVersion?: string;
46	  public maxCoreVersion?: string;
47	
48	  protected config?: Record<string, unknown>;
49	  protected extensionPoints: ExtensionPoint[] = [];
50	
51	  constructor(metadata: PluginMetadata) {
52	    this.id = metadata.id;
53	    this.name = metadata.name;
54	    this.version = metadata.version;
55	    this.description = metadata.description;
56	    this.author = metadata.author;
57	    this.homepage = metadata.homepage;
58	  }
59	
60	  /**
61	   * Initialize the plugin with optional configuration
62	   */
63	  async initialize(config?: Record<string, unknown>): Promise<void> {
64	    this.config = config;
65	    await this.onInitialize();
66	  }
67	
68	  /**
69	   * Shutdown the plugin and release resources
70	   */
71	  async shutdown(): Promise<void> {
72	    await this.onShutdown();
73	  }
74	
75	  /**
76	   * Get all extension points registered by this plugin
77	   */
78	  getExtensionPoints(): ExtensionPoint[] {
79	    return this.extensionPoints;
80	  }
81	
82	  /**
83	   * Register an extension point
84	   */
85	  protected registerExtensionPoint(
86	    name: string,
87	    handler: (context: unknown) => Promise<unknown>,
88	    priority?: number
89	  ): void {
90	    this.extensionPoints.push({ name, handler, priority });
91	  }
