2	/**
3	 * V3 MCP Server Entry Point
4	 *
5	 * Main entry point for the MCP server process.
6	 * Loads all tools from tools/index.ts and starts the server.
7	 *
8	 * Usage:
9	 *   npx tsx v3/mcp/server-entry.ts [options]
10	 *
11	 * Options:
12	 *   --transport <type>  Transport type: stdio, http, websocket (default: stdio)
13	 *   --host <host>       Server host (default: localhost)
14	 *   --port <port>       Server port (default: 3000)
15	 *   --tools <list>      Comma-separated tool list or "all" (default: all)
16	 *   --log-level <level> Log level: debug, info, warn, error (default: info)
17	 *
18	 * @module @claude-flow/mcp/server-entry
19	 * @version 3.0.0
20	 */
21	
22	import { MCPServer, createMCPServer } from './server.js';
23	import { getAllTools, getToolStats, validateToolRegistration } from './tools/index.js';
24	import type { ILogger, TransportType, MCPServerConfig } from './types.js';
25	
26	/**
27	 * Parse command line arguments
28	 */
29	function parseArgs(): {
30	  transport: TransportType;
31	  host: string;
32	  port: number;
33	  tools: string[];
34	  logLevel: 'debug' | 'info' | 'warn' | 'error';
35	} {
36	  const args = process.argv.slice(2);
37	  const options = {
38	    transport: 'stdio' as TransportType,
39	    host: 'localhost',
40	    port: 3000,
41	    tools: ['all'],
42	    logLevel: 'info' as 'debug' | 'info' | 'warn' | 'error',
43	  };
44	
45	  for (let i = 0; i < args.length; i++) {
46	    const arg = args[i];
47	    const nextArg = args[i + 1];
48	
49	    switch (arg) {
50	      case '--transport':
51	      case '-t':
52	        if (nextArg && ['stdio', 'http', 'websocket'].includes(nextArg)) {
53	          options.transport = nextArg as TransportType;
54	          i++;
55	        }
56	        break;
57	
58	      case '--host':
59	      case '-h':
60	        if (nextArg && !nextArg.startsWith('-')) {
61	          options.host = nextArg;
62	          i++;
63	        }
64	        break;
65	
66	      case '--port':
67	      case '-p':
68	        if (nextArg && !isNaN(parseInt(nextArg))) {
69	          options.port = parseInt(nextArg);
70	          i++;
71	        }
72	        break;
73	
74	      case '--tools':
75	        if (nextArg && !nextArg.startsWith('-')) {
76	          options.tools = nextArg === 'all' ? ['all'] : nextArg.split(',');
77	          i++;
78	        }
79	        break;
80	
81	      case '--log-level':
82	      case '-l':
83	        if (nextArg && ['debug', 'info', 'warn', 'error'].includes(nextArg)) {
84	          options.logLevel = nextArg as typeof options.logLevel;
85	          i++;
86	        }
87	        break;
88	
89	      case '--help':
90	        showHelp();
91	        process.exit(0);
92	    }
93	  }
94	
95	  return options;
96	}
97	
98	/**
99	 * Show help message
100	 */
101	function showHelp(): void {
102	  console.log(`
103	Claude-Flow MCP Server V3
104	
105	Usage:
106	  npx tsx v3/mcp/server-entry.ts [options]
107	
108	Options:
109	  --transport, -t <type>   Transport type: stdio, http, websocket (default: stdio)
110	  --host, -h <host>        Server host (default: localhost)
111	  --port, -p <port>        Server port (default: 3000)
112	  --tools <list>           Comma-separated tool list or "all" (default: all)
113	  --log-level, -l <level>  Log level: debug, info, warn, error (default: info)
114	  --help                   Show this help message
115	
116	Examples:
117	  npx tsx v3/mcp/server-entry.ts
118	  npx tsx v3/mcp/server-entry.ts --transport http --port 8080
119	  npx tsx v3/mcp/server-entry.ts --tools agent/spawn,swarm/init
120	`);
121	}
122	
123	/**
124	 * Create logger instance
125	 */
126	function createLogger(level: 'debug' | 'info' | 'warn' | 'error'): ILogger {
127	  const levels = ['debug', 'info', 'warn', 'error'];
128	  const minLevel = levels.indexOf(level);
129	
130	  const shouldLog = (logLevel: string): boolean => {
131	    return levels.indexOf(logLevel) >= minLevel;
132	  };
133	
134	  const formatMessage = (logLevel: string, msg: string, data?: unknown): string => {
135	    const timestamp = new Date().toISOString();
136	    const dataStr = data ? ` ${JSON.stringify(data)}` : '';
137	    return `[${timestamp}] [${logLevel.toUpperCase()}] ${msg}${dataStr}`;
138	  };
139	
140	  return {
141	    debug: (msg: string, data?: unknown) => {
142	      if (shouldLog('debug')) {
143	        console.debug(formatMessage('debug', msg, data));
144	      }
145	    },
146	    info: (msg: string, data?: unknown) => {
147	      if (shouldLog('info')) {
148	        console.info(formatMessage('info', msg, data));
149	      }
150	    },
151	    warn: (msg: string, data?: unknown) => {
152	      if (shouldLog('warn')) {
153	        console.warn(formatMessage('warn', msg, data));
154	      }
155	    },
156	    error: (msg: string, data?: unknown) => {
157	      if (shouldLog('error')) {
158	        console.error(formatMessage('error', msg, data));
159	      }
160	    },
161	  };
162	}
163	
164	/**
165	 * Initialize tool context with services
166	 */
167	function createToolContext(): Record<string, unknown> {
168	  return {
169	    sessionId: `server-${Date.now().toString(36)}`,
170	    orchestrator: null, // Will be injected when available
171	    swarmCoordinator: null, // Will be injected when available
172	    agentManager: null, // Will be injected when available
173	    metadata: {
174	      serverMode: true,
175	      startedAt: new Date().toISOString(),
176	    },
177	  };
178	}
179	
180	/**
181	 * Main server initialization
182	 */
183	async function main(): Promise<void> {
184	  const options = parseArgs();
185	  const logger = createLogger(options.logLevel);
186	
187	  logger.info('Starting Claude-Flow MCP Server V3', {
188	    transport: options.transport,
189	    host: options.host,
190	    port: options.port,
191	  });
192	
193	  // Validate tools before starting
194	  const validation = validateToolRegistration();
195	  if (!validation.valid) {
196	    logger.warn('Tool validation warnings', {
197	      issues: validation.issues,
198	    });
199	  }
200	
201	  // Get tool statistics
202	  const stats = getToolStats();
203	  logger.info('Tool registry initialized', {
204	    total: stats.total,
205	    categories: stats.categories,
206	    cacheable: stats.cacheable,
207	  });
208	
209	  // Server configuration
210	  const config: Partial<MCPServerConfig> = {
211	    name: 'Claude-Flow MCP Server V3',
212	    version: '3.0.0',
213	    transport: options.transport,
214	    host: options.host,
215	    port: options.port,
216	    enableMetrics: true,
217	    enableCaching: true,
218	    cacheTTL: 10000,
219	    logLevel: options.logLevel,
220	    requestTimeout: 30000,
221	    maxRequestSize: 10 * 1024 * 1024,
222	  };
223	
224	  // Create server
225	  const server = createMCPServer(config, logger);
226	
227	  // Setup graceful shutdown
228	  const shutdown = async (signal: string): Promise<void> => {
229	    logger.info(`Received ${signal}, shutting down gracefully...`);
230	
231	    try {
232	      await server.stop();
233	      logger.info('Server stopped successfully');
234	      process.exit(0);
235	    } catch (error) {
236	      logger.error('Error during shutdown', { error });
237	      process.exit(1);
238	    }
239	  };
240	
241	  process.on('SIGTERM', () => shutdown('SIGTERM'));
242	  process.on('SIGINT', () => shutdown('SIGINT'));
243	  process.on('SIGHUP', () => shutdown('SIGHUP'));
244	
245	  // Handle uncaught errors
246	  process.on('uncaughtException', (error) => {
247	    logger.error('Uncaught exception', { error });
248	    shutdown('uncaughtException');
249	  });
250	
251	  process.on('unhandledRejection', (reason) => {
252	    logger.error('Unhandled rejection', { reason });
253	  });
254	
255	  // Server event handlers
256	  server.on('server:started', (data) => {
257	    logger.info('Server started', data);
258	
259	    // Send ready signal for stdio transport
260	    if (options.transport === 'stdio') {
261	      // Write ready notification
262	      const notification = {
263	        jsonrpc: '2.0',
264	        method: 'notifications/server/ready',
265	        params: {
266	          serverInfo: {
267	            name: 'Claude-Flow MCP Server V3',
268	            version: '3.0.0',
269	          },
270	          tools: stats.total,
271	        },
272	      };
273	      console.log(JSON.stringify(notification));
274	    }
275	  });
276	
277	  server.on('tool:registered', (name) => {
278	    logger.debug('Tool registered', { name });
279	  });
280	
281	  server.on('tool:called', (data) => {
282	    logger.debug('Tool called', data);
283	  });
284	
285	  server.on('tool:completed', (data) => {
286	    logger.debug('Tool completed', data);
287	  });
288	
289	  server.on('tool:error', (data) => {
290	    logger.error('Tool error', data);
291	  });
292	
293	  server.on('session:created', (session) => {
294	    logger.info('Session created', { id: session.id });
295	  });
296	
297	  server.on('session:closed', (data) => {
298	    logger.info('Session closed', data);
299	  });
300	
301	  // Start server
302	  try {
303	    await server.start();
304	
305	    if (options.transport !== 'stdio') {
306	      logger.info(`MCP Server listening on ${options.host}:${options.port}`);
307	      logger.info(`Health check: http://${options.host}:${options.port}/health`);
308	      logger.info(`RPC endpoint: http://${options.host}:${options.port}/rpc`);
309	    }
310	  } catch (error) {
311	    logger.error('Failed to start server', { error });
312	    process.exit(1);
313	  }
314	}
315	
316	// Run main
317	main().catch((error) => {
318	  console.error('Fatal error:', error);
319	  process.exit(1);
320	});
