61	/**
62	 * MCP Server Interface
63	 */
64	export interface IMCPServer {
65	  start(): Promise<void>;
66	  stop(): Promise<void>;
67	  registerTool(tool: MCPTool): boolean;
68	  registerTools(tools: MCPTool[]): { registered: number; failed: string[] };
69	  getHealthStatus(): Promise<{
