80	/**
81	 * V3 MCP Server
82	 */
83	export class MCPServer extends EventEmitter implements IMCPServer {
84	  private readonly config: MCPServerConfig;
85	  private readonly toolRegistry: ToolRegistry;
86	  private readonly sessionManager: SessionManager;
87	  private readonly connectionPool?: ConnectionPool;
88	  private readonly transportManager: TransportManager;
89	  private transport?: ITransport;
90	  private running = false;
91	  private startTime?: Date;
92	  private startupDuration?: number;
93	  private currentSession?: MCPSession;
94	
95	  // Server information
96	  private readonly serverInfo = {
97	    name: 'Claude-Flow MCP Server V3',
98	    version: '3.0.0',
99	  };
100	
101	  // Protocol version
102	  private readonly protocolVersion: MCPProtocolVersion = {
103	    major: 2024,
104	    minor: 11,
105	    patch: 5,
106	  };
107	
108	  // Server capabilities
109	  private readonly capabilities: MCPCapabilities = {
110	    logging: { level: 'info' },
111	    tools: { listChanged: true },
112	    resources: { listChanged: false, subscribe: false },
113	    prompts: { listChanged: false },
114	  };
115	
116	  // Request statistics
117	  private requestStats = {
118	    total: 0,
119	    successful: 0,
120	    failed: 0,
121	    totalResponseTime: 0,
122	  };
123	
124	  constructor(
125	    config: Partial<MCPServerConfig>,
126	    private readonly logger: ILogger,
127	    private readonly orchestrator?: unknown,
128	    private readonly swarmCoordinator?: unknown
129	  ) {
130	    super();
131	    this.config = { ...DEFAULT_CONFIG, ...config } as MCPServerConfig;
132	
133	    // Initialize components
134	    this.toolRegistry = createToolRegistry(logger);
135	    this.sessionManager = createSessionManager(logger, {
136	      maxSessions: 100,
137	      sessionTimeout: 30 * 60 * 1000,
138	    });
139	    this.transportManager = createTransportManager(logger);
140	
141	    // Initialize connection pool if enabled
142	    if (this.config.connectionPool) {
143	      this.connectionPool = createConnectionPool(
144	        this.config.connectionPool,
145	        logger,
146	        this.config.transport
147	      );
148	    }
149	
150	    // Setup event handlers
151	    this.setupEventHandlers();
152	  }
153	
154	  /**
155	   * Start the MCP server
156	   */
157	  async start(): Promise<void> {
158	    if (this.running) {
159	      throw new MCPServerError('Server already running');
160	    }
161	
162	    const startTime = performance.now();
163	    this.startTime = new Date();
164	
165	    this.logger.info('Starting MCP server', {
166	      name: this.config.name,
167	      version: this.config.version,
168	      transport: this.config.transport,
169	    });
170	
171	    try {
172	      // Create and start transport
173	      this.transport = createTransport(this.config.transport, this.logger, {
174	        type: this.config.transport,
175	        host: this.config.host,
176	        port: this.config.port,
177	        corsEnabled: this.config.corsEnabled,
178	        corsOrigins: this.config.corsOrigins,
179	        auth: this.config.auth,
180	        maxRequestSize: String(this.config.maxRequestSize),
181	        requestTimeout: this.config.requestTimeout,
182	      } as any);
183	
184	      // Setup request handler
185	      this.transport.onRequest(async (request) => {
186	        return await this.handleRequest(request);
187	      });
188	
189	      // Setup notification handler
190	      this.transport.onNotification(async (notification) => {
191	        await this.handleNotification(notification);
192	      });
193	
194	      // Start transport
195	      await this.transport.start();
196	
197	      // Register built-in tools
198	      await this.registerBuiltInTools();
199	
200	      this.running = true;
201	      this.startupDuration = performance.now() - startTime;
202	
203	      this.logger.info('MCP server started', {
204	        startupTime: `${this.startupDuration.toFixed(2)}ms`,
205	        tools: this.toolRegistry.getToolCount(),
206	      });
207	
208	      this.emit('server:started', {
209	        startupTime: this.startupDuration,
210	        tools: this.toolRegistry.getToolCount(),
211	      });
212	
213	    } catch (error) {
214	      this.logger.error('Failed to start MCP server', { error });
215	      throw new MCPServerError('Failed to start server', ErrorCodes.INTERNAL_ERROR, { error });
216	    }
217	  }
218	
219	  /**
220	   * Stop the MCP server
221	   */
222	  async stop(): Promise<void> {
223	    if (!this.running) {
224	      return;
225	    }
226	
227	    this.logger.info('Stopping MCP server');
228	
229	    try {
230	      // Stop transport
231	      if (this.transport) {
232	        await this.transport.stop();
233	        this.transport = undefined;
234	      }
235	
236	      // Clear sessions
237	      this.sessionManager.clearAll();
238	
239	      // Clear connection pool
240	      if (this.connectionPool) {
241	        await this.connectionPool.clear();
242	      }
243	
244	      this.running = false;
245	      this.currentSession = undefined;
246	
247	      this.logger.info('MCP server stopped');
248	      this.emit('server:stopped');
249	
250	    } catch (error) {
251	      this.logger.error('Error stopping MCP server', { error });
252	      throw error;
253	    }
254	  }
255	
256	  /**
257	   * Register a tool
258	   */
259	  registerTool(tool: MCPTool): boolean {
260	    return this.toolRegistry.register(tool);
261	  }
262	
263	  /**
264	   * Register multiple tools
265	   */
266	  registerTools(tools: MCPTool[]): { registered: number; failed: string[] } {
267	    return this.toolRegistry.registerBatch(tools);
268	  }
269	
270	  /**
271	   * Unregister a tool
272	   */
273	  unregisterTool(name: string): boolean {
274	    return this.toolRegistry.unregister(name);
275	  }
276	
277	  /**
278	   * Get health status
279	   */
280	  async getHealthStatus(): Promise<{
281	    healthy: boolean;
282	    error?: string;
283	    metrics?: Record<string, number>;
284	  }> {
285	    try {
286	      const transportHealth = this.transport
287	        ? await this.transport.getHealthStatus()
288	        : { healthy: false, error: 'Transport not initialized' };
289	
290	      const sessionMetrics = this.sessionManager.getSessionMetrics();
291	      const poolStats = this.connectionPool?.getStats();
292	
293	      const metrics: Record<string, number> = {
294	        registeredTools: this.toolRegistry.getToolCount(),
295	        totalRequests: this.requestStats.total,
296	        successfulRequests: this.requestStats.successful,
297	        failedRequests: this.requestStats.failed,
298	        totalSessions: sessionMetrics.total,
299	        activeSessions: sessionMetrics.active,
300	        ...(transportHealth.metrics || {}),
301	      };
302	
303	      if (poolStats) {
304	        metrics.poolConnections = poolStats.totalConnections;
305	        metrics.poolIdleConnections = poolStats.idleConnections;
306	        metrics.poolBusyConnections = poolStats.busyConnections;
307	      }
308	
309	      return {
310	        healthy: this.running && transportHealth.healthy,
311	        error: transportHealth.error,
312	        metrics,
313	      };
314	
315	    } catch (error) {
316	      return {
317	        healthy: false,
318	        error: error instanceof Error ? error.message : 'Unknown error',
319	      };
320	    }
321	  }
322	
323	  /**
324	   * Get server metrics
325	   */
326	  getMetrics(): MCPServerMetrics {
327	    const sessionMetrics = this.sessionManager.getSessionMetrics();
328	    const registryStats = this.toolRegistry.getStats();
329	
330	    return {
331	      totalRequests: this.requestStats.total,
332	      successfulRequests: this.requestStats.successful,
333	      failedRequests: this.requestStats.failed,
334	      averageResponseTime: this.requestStats.total > 0
335	        ? this.requestStats.totalResponseTime / this.requestStats.total
336	        : 0,
337	      activeSessions: sessionMetrics.active,
338	      toolInvocations: Object.fromEntries(
339	        registryStats.topTools.map((t) => [t.name, t.calls])
340	      ),
341	      errors: {},
342	      lastReset: this.startTime || new Date(),
343	      startupTime: this.startupDuration,
344	      uptime: this.startTime ? Date.now() - this.startTime.getTime() : 0,
345	    };
346	  }
347	
348	  /**
349	   * Get all sessions
350	   */
351	  getSessions(): MCPSession[] {
352	    return this.sessionManager.getActiveSessions();
353	  }
354	
355	  /**
356	   * Get session by ID
357	   */
358	  getSession(sessionId: string): MCPSession | undefined {
359	    return this.sessionManager.getSession(sessionId);
360	  }
361	
362	  /**
363	   * Terminate a session
364	   */
365	  terminateSession(sessionId: string): boolean {
366	    const result = this.sessionManager.closeSession(sessionId, 'Terminated by server');
367	    if (this.currentSession?.id === sessionId) {
368	      this.currentSession = undefined;
369	    }
370	    return result;
371	  }
372	
373	  /**
374	   * Handle incoming request
375	   */
376	  private async handleRequest(request: MCPRequest): Promise<MCPResponse> {
377	    const startTime = performance.now();
378	    this.requestStats.total++;
379	
380	    this.logger.debug('Handling request', {
381	      id: request.id,
382	      method: request.method,
383	    });
384	
385	    try {
386	      // Handle initialization
387	      if (request.method === 'initialize') {
388	        return await this.handleInitialize(request);
389	      }
390	
391	      // Get or create session
392	      const session = this.getOrCreateSession();
393	
394	      // Check initialization
395	      if (!session.isInitialized && request.method !== 'initialized') {
396	        return this.createErrorResponse(
397	          request.id,
398	          ErrorCodes.SERVER_NOT_INITIALIZED,
399	          'Server not initialized'
400	        );
401	      }
402	
403	      // Update session activity
404	      this.sessionManager.updateActivity(session.id);
405	
406	      // Route request
407	      const response = await this.routeRequest(request);
408	
409	      const duration = performance.now() - startTime;
410	      this.requestStats.successful++;
411	      this.requestStats.totalResponseTime += duration;
412	
413	      this.logger.debug('Request completed', {
414	        id: request.id,
415	        method: request.method,
416	        duration: `${duration.toFixed(2)}ms`,
417	      });
418	
419	      return response;
420	
421	    } catch (error) {
422	      const duration = performance.now() - startTime;
423	      this.requestStats.failed++;
424	      this.requestStats.totalResponseTime += duration;
425	
426	      this.logger.error('Request failed', {
427	        id: request.id,
428	        method: request.method,
429	        error,
430	      });
431	
432	      return this.createErrorResponse(
433	        request.id,
434	        ErrorCodes.INTERNAL_ERROR,
435	        error instanceof Error ? error.message : 'Internal error'
436	      );
437	    }
438	  }
