440	  /**
441	   * Handle notification
442	   */
443	  private async handleNotification(notification: MCPNotification): Promise<void> {
444	    this.logger.debug('Handling notification', { method: notification.method });
445	
446	    switch (notification.method) {
447	      case 'initialized':
448	        this.logger.info('Client initialized notification received');
449	        break;
450	
451	      case 'notifications/cancelled':
452	        this.logger.debug('Request cancelled', notification.params);
453	        break;
454	
455	      default:
456	        this.logger.debug('Unknown notification', { method: notification.method });
457	    }
458	  }
