460	  /**
461	   * Handle initialize request
462	   */
463	  private async handleInitialize(request: MCPRequest): Promise<MCPResponse> {
464	    const params = request.params as MCPInitializeParams;
465	
466	    if (!params) {
467	      return this.createErrorResponse(
468	        request.id,
469	        ErrorCodes.INVALID_PARAMS,
470	        'Invalid params'
471	      );
472	    }
473	
474	    // Create and initialize session
475	    const session = this.sessionManager.createSession(this.config.transport);
476	    this.sessionManager.initializeSession(session.id, params);
477	    this.currentSession = session;
478	
479	    const result: MCPInitializeResult = {
480	      protocolVersion: this.protocolVersion,
481	      capabilities: this.capabilities,
482	      serverInfo: this.serverInfo,
483	      instructions: 'Claude-Flow MCP Server V3 ready for tool execution',
484	    };
485	
486	    this.logger.info('Session initialized', {
487	      sessionId: session.id,
488	      clientInfo: params.clientInfo,
489	    });
490	
491	    return {
492	      jsonrpc: '2.0',
493	      id: request.id,
494	      result,
495	    };
496	  }
497	
498	  /**
499	   * Route request to appropriate handler
500	   */
501	  private async routeRequest(request: MCPRequest): Promise<MCPResponse> {
502	    switch (request.method) {
503	      case 'tools/list':
504	        return this.handleToolsList(request);
505	
506	      case 'tools/call':
507	        return this.handleToolsCall(request);
508	
509	      case 'resources/list':
510	        return this.handleResourcesList(request);
511	
512	      case 'prompts/list':
513	        return this.handlePromptsList(request);
514	
515	      case 'ping':
516	        return {
517	          jsonrpc: '2.0',
518	          id: request.id,
519	          result: { pong: true, timestamp: Date.now() },
520	        };
521	
522	      default:
523	        // Try to execute as tool call (backwards compatibility)
524	        if (this.toolRegistry.hasTool(request.method)) {
525	          return this.handleToolExecution(request);
526	        }
527	
528	        return this.createErrorResponse(
529	          request.id,
530	          ErrorCodes.METHOD_NOT_FOUND,
531	          `Method not found: ${request.method}`
532	        );
533	    }
534	  }
535	
536	  /**
537	   * Handle tools/list request
538	   */
539	  private handleToolsList(request: MCPRequest): MCPResponse {
540	    const tools = this.toolRegistry.listTools().map((t) => ({
541	      name: t.name,
542	      description: t.description,
543	      inputSchema: this.toolRegistry.getTool(t.name)?.inputSchema,
544	    }));
545	
546	    return {
547	      jsonrpc: '2.0',
548	      id: request.id,
549	      result: { tools },
550	    };
551	  }
552	
553	  /**
554	   * Handle tools/call request
555	   */
556	  private async handleToolsCall(request: MCPRequest): Promise<MCPResponse> {
557	    const params = request.params as { name: string; arguments?: Record<string, unknown> };
558	
559	    if (!params?.name) {
560	      return this.createErrorResponse(
561	        request.id,
562	        ErrorCodes.INVALID_PARAMS,
563	        'Tool name is required'
564	      );
565	    }
566	
567	    const context: ToolContext = {
568	      sessionId: this.currentSession?.id || 'unknown',
569	      requestId: request.id,
570	      orchestrator: this.orchestrator,
571	      swarmCoordinator: this.swarmCoordinator,
572	    };
573	
574	    const result = await this.toolRegistry.execute(
575	      params.name,
576	      params.arguments || {},
577	      context
578	    );
579	
580	    return {
581	      jsonrpc: '2.0',
582	      id: request.id,
583	      result,
584	    };
585	  }
586	
587	  /**
588	   * Handle direct tool execution (backwards compatibility)
589	   */
590	  private async handleToolExecution(request: MCPRequest): Promise<MCPResponse> {
591	    const context: ToolContext = {
592	      sessionId: this.currentSession?.id || 'unknown',
593	      requestId: request.id,
594	      orchestrator: this.orchestrator,
595	      swarmCoordinator: this.swarmCoordinator,
596	    };
597	
598	    const result = await this.toolRegistry.execute(
599	      request.method,
600	      (request.params as Record<string, unknown>) || {},
601	      context
602	    );
603	
604	    return {
605	      jsonrpc: '2.0',
606	      id: request.id,
607	      result,
608	    };
609	  }
