633	  /**
634	   * Get or create current session
635	   */
636	  private getOrCreateSession(): MCPSession {
637	    if (this.currentSession) {
638	      return this.currentSession;
639	    }
640	
641	    const session = this.sessionManager.createSession(this.config.transport);
642	    this.currentSession = session;
