661	  /**
662	   * Register built-in tools
663	   */
664	  private async registerBuiltInTools(): Promise<void> {
665	    const startTime = performance.now();
666	
667	    // Register all ADR-005 MCP-first tools
668	    const { getAllTools } = await import('./tools/index.js');
669	    const mcpTools = getAllTools();
670	
671	    const mcpResult = this.registerTools(mcpTools);
672	
673	    this.logger.info('MCP-first tools registered (ADR-005)', {
674	      registered: mcpResult.registered,
675	      failed: mcpResult.failed.length,
676	      failedTools: mcpResult.failed,
677	    });
678	
679	    // System info tool
680	    this.registerTool({
681	      name: 'system/info',
682	      description: 'Get system information',
683	      inputSchema: { type: 'object', properties: {} },
684	      handler: async () => ({
685	        name: this.serverInfo.name,
686	        version: this.serverInfo.version,
687	        platform: platform(),
688	        arch: arch(),
689	        runtime: 'Node.js',
690	        uptime: this.startTime ? Date.now() - this.startTime.getTime() : 0,
691	      }),
692	      category: 'system',
693	    });
694	
695	    // Health check tool
696	    this.registerTool({
697	      name: 'system/health',
698	      description: 'Get system health status',
699	      inputSchema: { type: 'object', properties: {} },
700	      handler: async () => await this.getHealthStatus(),
701	      category: 'system',
702	      cacheable: true,
703	      cacheTTL: 2000,
704	    });
705	
706	    // Metrics tool
707	    this.registerTool({
708	      name: 'system/metrics',
709	      description: 'Get server metrics',
710	      inputSchema: { type: 'object', properties: {} },
711	      handler: async () => this.getMetrics(),
712	      category: 'system',
713	      cacheable: true,
714	      cacheTTL: 1000,
715	    });
716	
717	    // Tools list tool
718	    this.registerTool({
719	      name: 'tools/list-detailed',
720	      description: 'List all registered tools with details',
721	      inputSchema: {
722	        type: 'object',
723	        properties: {
724	          category: { type: 'string', description: 'Filter by category' },
725	        },
726	      },
727	      handler: async (input: { category?: string }) => {
728	        if (input.category) {
729	          return this.toolRegistry.getByCategory(input.category);
730	        }
731	        return this.toolRegistry.listTools();
732	      },
733	      category: 'system',
734	    });
735	
736	    const duration = performance.now() - startTime;
737	
738	    this.logger.info('Built-in tools registered', {
739	      mcpTools: mcpResult.registered,
740	      systemTools: 4,
741	      totalTools: mcpResult.registered + 4,
742	      registrationTime: `${duration.toFixed(2)}ms`,
743	    });
744	  }
