746	  /**
747	   * Setup event handlers
748	   */
749	  private setupEventHandlers(): void {
750	    // Tool events
751	    this.toolRegistry.on('tool:registered', (name) => {
752	      this.emit('tool:registered', name);
753	    });
754	
755	    this.toolRegistry.on('tool:called', (data) => {
756	      this.emit('tool:called', data);
757	    });
758	
759	    this.toolRegistry.on('tool:completed', (data) => {
760	      this.emit('tool:completed', data);
761	    });
762	
763	    this.toolRegistry.on('tool:error', (data) => {
764	      this.emit('tool:error', data);
765	    });
766	
767	    // Session events
768	    this.sessionManager.on('session:created', (session) => {
769	      this.emit('session:created', session);
770	    });
771	
772	    this.sessionManager.on('session:closed', (data) => {
773	      this.emit('session:closed', data);
774	    });
775	
776	    this.sessionManager.on('session:expired', (session) => {
777	      this.emit('session:expired', session);
778	    });
779	  }
